import React, { useState } from 'react';
import { Product, HistoryItem, SaleItem, Sale } from '../types';
import { ShoppingCart, Plus, Minus, Trash2, Search, FileText, Package, CreditCard, Banknote, Truck, ArrowRight, Grid } from 'lucide-react';
import clsx from 'clsx';

interface POSInterfaceProps {
  products: Product[];
  jobs: HistoryItem[];
  cart: SaleItem[];
  currency: (val: number) => string;
  onAddToCart: (item: SaleItem) => void;
  onUpdateCartQty: (index: number, delta: number) => void;
  onRemoveFromCart: (index: number) => void;
  onCheckout: (paymentMethod: Sale['paymentMethod'], shipping: number) => Promise<void>;
  onClearCart: () => void;
}

export const POSInterface: React.FC<POSInterfaceProps> = ({ 
  products, jobs, cart, currency, 
  onAddToCart, onUpdateCartQty, onRemoveFromCart, onCheckout, onClearCart
}) => {
  const [activeTab, setActiveTab] = useState<'products' | 'jobs'>('products');
  const [mobileView, setMobileView] = useState<'catalog' | 'cart'>('catalog'); // Mobile View Toggle
  const [searchTerm, setSearchTerm] = useState('');
  const [paymentModalOpen, setPaymentModalOpen] = useState(false);
  const [shipping, setShipping] = useState<string>(''); 

  // Cart Totals
  const subtotal = cart.reduce((sum, item) => sum + (item.unitPrice * item.quantity), 0);
  const shippingCost = parseFloat(shipping) || 0;
  const cartItemCount = cart.reduce((sum, item) => sum + item.quantity, 0);

  // Tax Total for display (optional)
  const totalTax = cart.reduce((sum, item) => {
      const rate = item.taxRate || 0;
      const netPrice = item.unitPrice / (1 + (rate/100));
      return sum + ((item.unitPrice - netPrice) * item.quantity);
  }, 0);

  const finalTotal = subtotal + shippingCost;

  // Filtering
  const filteredProducts = products.filter(p => p.name.toLowerCase().includes(searchTerm.toLowerCase()));
  const filteredJobs = jobs.filter(j => j.name.toLowerCase().includes(searchTerm.toLowerCase()));

  const handleProductClick = (p: Product) => {
    // Check stock limit
    const existingItem = cart.find(i => i.refId === p.id && i.type === 'product');
    const currentQty = existingItem ? existingItem.quantity : 0;

    if (currentQty >= p.stock) {
        return; // Do nothing if stock exhausted
    }

    onAddToCart({
      type: 'product',
      refId: p.id,
      name: p.name,
      quantity: 1,
      unitPrice: p.price,
      unitCost: p.cost,
      laborCost: p.laborCost || 0, // Pass labor cost, default to 0
      energyCost: p.energyCost || 0, // Pass energy cost, default to 0
      taxRate: p.taxRate || 0
    });
  };

  const handleJobClick = (j: HistoryItem) => {
    // Attempt to extract tax rate from job inputs
    let tax = 0;
    if (j.inputs && j.inputs.taxRate) {
        tax = typeof j.inputs.taxRate === 'number' ? j.inputs.taxRate : parseFloat(j.inputs.taxRate);
    }

    // Extract Labor & Energy from snapshot if available
    const labor = j.resultsSnapshot?.unit.labor;
    // Energy cost usually includes depreciation in "machine time" context, but strictly energy is energy.
    // Let's pass the raw energy value from snapshot.
    const energy = j.resultsSnapshot?.unit.energy;

    onAddToCart({
      type: 'job',
      refId: j.id,
      name: j.name,
      quantity: typeof j.inputs.batchQty === 'string' ? parseFloat(j.inputs.batchQty) : j.inputs.batchQty,
      unitPrice: j.resultsSnapshot?.unit.finalPrice || 0,
      unitCost: j.resultsSnapshot?.unit.productionCost || 0,
      laborCost: labor || 0,
      energyCost: energy || 0,
      taxRate: tax || 0
    });
  };

  const handleQtyChange = (index: number, delta: number) => {
      const item = cart[index];
      if (item.type === 'product' && delta > 0) {
          const product = products.find(p => p.id === item.refId);
          if (product && item.quantity >= product.stock) {
              return; // Limit reached
          }
      }
      onUpdateCartQty(index, delta);
  };

  const handlePayment = (method: Sale['paymentMethod']) => {
      onCheckout(method, shippingCost);
      setPaymentModalOpen(false);
      setShipping(''); // Reset shipping after checkout
      setMobileView('catalog'); // Return to catalog
  };

  return (
    <div className="flex flex-col md:flex-row h-[calc(100vh-64px)] md:h-[calc(100vh-64px)] overflow-hidden relative">

      {/* LEFT PANEL: CATALOG */}
      <div className={clsx(
          "flex-1 flex flex-col bg-gray-50 border-r border-gray-200 h-full",
          mobileView === 'cart' ? 'hidden md:flex' : 'flex'
      )}>
        {/* Search & Tabs */}
        <div className="p-4 bg-white border-b border-gray-200 shadow-sm z-10">
          <div className="flex gap-2 mb-4">
             <button 
                onClick={() => setActiveTab('products')}
                className={`flex-1 py-2 text-sm font-bold rounded-lg flex items-center justify-center gap-2 transition-colors ${activeTab === 'products' ? 'bg-brand-600 text-white' : 'bg-gray-100 text-gray-600 hover:bg-gray-200'}`}
             >
               <Package size={16} /> Products
             </button>
             <button 
                onClick={() => setActiveTab('jobs')}
                className={`flex-1 py-2 text-sm font-bold rounded-lg flex items-center justify-center gap-2 transition-colors ${activeTab === 'jobs' ? 'bg-brand-600 text-white' : 'bg-gray-100 text-gray-600 hover:bg-gray-200'}`}
             >
               <FileText size={16} /> Saved Jobs
             </button>
          </div>
          <div className="relative">
            <Search className="absolute left-3 top-2.5 text-gray-400" size={18} />
            <input 
              className="w-full pl-10 pr-4 py-2 border border-gray-200 rounded-lg text-sm focus:ring-2 focus:ring-brand-500"
              placeholder="Search items..."
              value={searchTerm}
              onChange={e => setSearchTerm(e.target.value)}
            />
          </div>
        </div>

        {/* Grid/List Content */}
        <div className="flex-1 overflow-y-auto p-4 pb-20 md:pb-4">
          {activeTab === 'products' ? (
             <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-3">
               {filteredProducts.map(p => {
                 const inCart = cart.find(i => i.refId === p.id && i.type === 'product')?.quantity || 0;
                 const isOutOfStock = p.stock <= 0 || inCart >= p.stock;

                 return (
                    <div 
                        key={p.id} 
                        onClick={() => !isOutOfStock && handleProductClick(p)}
                        className={clsx(
                            "bg-white p-3 rounded-xl border border-gray-200 shadow-sm transition-all flex flex-col justify-between h-32",
                            isOutOfStock ? "opacity-50 grayscale cursor-not-allowed bg-gray-50" : "hover:border-brand-500 hover:shadow-md cursor-pointer"
                        )}
                    >
                        <div>
                        <h4 className="font-bold text-gray-800 text-sm line-clamp-2">{p.name}</h4>
                        <p className={clsx("text-xs mt-1", p.stock === 0 ? "text-red-500 font-bold" : "text-gray-500")}>
                            {p.stock === 0 ? "Out of Stock" : `${p.stock} in stock`}
                        </p>
                        </div>
                        <div className="flex justify-between items-end">
                            <div className="font-bold text-brand-600 text-lg">{currency(p.price)}</div>
                            {p.taxRate > 0 && <span className="text-[10px] text-gray-400">VAT {p.taxRate}%</span>}
                        </div>
                    </div>
                 );
               })}
             </div>
          ) : (
             <div className="space-y-2">
               {filteredJobs.map(j => (
                 <div 
                    key={j.id} 
                    onClick={() => handleJobClick(j)}
                    className="bg-white p-3 rounded-xl border border-gray-200 shadow-sm hover:border-brand-500 hover:shadow-md cursor-pointer transition-all flex justify-between items-center"
                 >
                    <div>
                      <h4 className="font-bold text-gray-800 text-sm">{j.name}</h4>
                      <p className="text-xs text-gray-500">{j.date}</p>
                    </div>
                    <div className="text-right">
                       <div className="font-bold text-brand-600">{currency(j.resultsSnapshot?.unit.finalPrice || 0)}</div>
                       <div className="text-xs text-gray-400">per unit</div>
                    </div>
                 </div>
               ))}
             </div>
          )}
        </div>

        {/* Mobile View Cart Button */}
        <div className="md:hidden absolute bottom-4 right-4 z-20">
             <button 
                onClick={() => setMobileView('cart')}
                className="bg-brand-600 text-white p-4 rounded-full shadow-lg flex items-center gap-2 relative"
             >
                 <ShoppingCart size={24} />
                 {cartItemCount > 0 && (
                     <span className="absolute -top-2 -right-2 bg-red-500 text-white text-xs font-bold w-6 h-6 rounded-full flex items-center justify-center">
                         {cartItemCount}
                     </span>
                 )}
             </button>
        </div>
      </div>

      {/* RIGHT PANEL: CART */}
      <div className={clsx(
          "w-full md:w-96 flex-col bg-white shadow-xl z-20 h-full",
          mobileView === 'cart' ? 'flex' : 'hidden md:flex'
      )}>
         <div className="p-4 bg-gray-900 text-white flex justify-between items-center">
            <div className="flex items-center gap-2">
                <button onClick={() => setMobileView('catalog')} className="md:hidden text-gray-400 hover:text-white">
                    <ArrowRight className="rotate-180" size={20} />
                </button>
                <h2 className="font-bold flex items-center gap-2"><ShoppingCart size={20} /> Current Sale</h2>
            </div>
            <button onClick={onClearCart} className="text-xs text-gray-400 hover:text-white">Clear</button>
         </div>

         <div className="flex-1 overflow-y-auto p-4 space-y-3">
            {cart.map((item, idx) => {
                const product = item.type === 'product' ? products.find(p => p.id === item.refId) : null;
                const isMax = product ? item.quantity >= product.stock : false;

                return (
                    <div key={idx} className="flex gap-2 items-center bg-gray-50 p-2 rounded-lg border border-gray-100">
                        <div className="flex-1">
                            <h4 className="text-sm font-bold text-gray-800 line-clamp-1">{item.name}</h4>
                            <div className="flex justify-between items-center pr-2">
                                <div className="text-xs text-brand-600 font-bold">{currency(item.unitPrice)}</div>
                                {item.taxRate > 0 && <span className="text-[9px] text-gray-400">Inc {item.taxRate}% Tax</span>}
                            </div>
                        </div>
                        <div className="flex items-center gap-2 bg-white border border-gray-200 rounded px-1 shadow-sm">
                            <button onClick={() => handleQtyChange(idx, -1)} className="p-1 text-gray-500 hover:text-red-600 transition-colors"><Minus size={12}/></button>
                            <span className="text-xs font-bold w-6 text-center text-gray-800 select-none">{item.quantity}</span>
                            <button 
                                onClick={() => handleQtyChange(idx, 1)} 
                                disabled={isMax}
                                className={clsx("p-1 transition-colors", isMax ? "text-gray-300 cursor-not-allowed" : "text-gray-500 hover:text-green-600")}
                            >
                                <Plus size={12}/>
                            </button>
                        </div>
                        <button onClick={() => onRemoveFromCart(idx)} className="text-gray-400 hover:text-red-500 p-1"><Trash2 size={16} /></button>
                    </div>
                );
            })}
            {cart.length === 0 && (
              <div className="text-center py-10 text-gray-400 text-sm italic">
                Cart is empty. Select items from the catalog.
              </div>
            )}
         </div>

         <div className="p-4 border-t border-gray-200 bg-gray-50 mb-16 md:mb-0">
            <div className="flex justify-between items-center mb-1 text-gray-500 text-xs">
               <span>Subtotal (Gross)</span>
               <span>{currency(subtotal)}</span>
            </div>

            <div className="flex justify-between items-center mb-1 text-gray-500 text-xs">
               <span className="flex items-center gap-1"><Truck size={12}/> Shipping</span>
               <div className="flex items-center w-24">
                 <span className="mr-1 text-gray-400">₱</span>
                 <input 
                   type="number" 
                   min="0"
                   step="0.01"
                   className="w-full text-right border border-gray-200 rounded px-1 py-0.5 text-xs bg-white focus:ring-1 focus:ring-brand-500 focus:outline-none"
                   placeholder="0.00"
                   value={shipping}
                   onChange={e => setShipping(e.target.value)}
                 />
               </div>
            </div>

            <div className="flex justify-between items-center mb-4 text-gray-400 text-xs">
               <span>Included VAT/Tax</span>
               <span>{currency(totalTax)}</span>
            </div>

            <div className="flex justify-between items-center mb-4 border-t border-gray-100 pt-2">
               <span className="text-gray-900 font-bold text-lg">Total</span>
               <span className="text-2xl font-black text-gray-900">{currency(finalTotal)}</span>
            </div>

            <button 
              disabled={cart.length === 0}
              onClick={() => setPaymentModalOpen(true)}
              className="w-full bg-brand-600 hover:bg-brand-700 disabled:bg-gray-300 disabled:cursor-not-allowed text-white py-3 rounded-xl font-bold text-lg shadow-lg shadow-brand-500/30 transition-all"
            >
              Checkout
            </button>
         </div>
      </div>

      {/* Payment Modal */}
      {paymentModalOpen && (
        <div className="fixed inset-0 bg-black/60 backdrop-blur-sm z-50 flex items-center justify-center">
           <div className="bg-white rounded-2xl w-full max-w-sm p-6 shadow-2xl animate-in fade-in zoom-in duration-200">
              <h3 className="text-lg font-bold text-gray-900 mb-4 text-center">Select Payment Method</h3>
              <div className="space-y-3">
                 <button onClick={() => handlePayment('cash')} className="w-full flex items-center justify-center gap-3 p-4 border border-gray-200 rounded-xl hover:border-green-500 hover:bg-green-50 font-bold text-gray-700">
                    <Banknote className="text-green-600" /> Cash
                 </button>
                 <button onClick={() => handlePayment('gcash')} className="w-full flex items-center justify-center gap-3 p-4 border border-gray-200 rounded-xl hover:border-blue-500 hover:bg-blue-50 font-bold text-gray-700">
                    <span className="text-blue-600 font-black">G</span> GCash
                 </button>
                 <button onClick={() => handlePayment('card')} className="w-full flex items-center justify-center gap-3 p-4 border border-gray-200 rounded-xl hover:border-purple-500 hover:bg-purple-50 font-bold text-gray-700">
                    <CreditCard className="text-purple-600" /> Card / Other
                 </button>
              </div>
              <button onClick={() => setPaymentModalOpen(false)} className="mt-4 w-full py-2 text-gray-400 hover:text-gray-600 text-sm">Cancel</button>
           </div>
        </div>
      )}

    </div>
  );
};

import React, { useState, useCallback } from 'react';
import { CalculatorInputs, CalculatedResults, HistoryItem } from '../types';
import { InputGroup } from './InputGroup';
import { SummaryChart } from './SummaryChart';
import { HistoryPanel } from './HistoryPanel';
import { 
  Upload, Box, Zap, TrendingUp, Save, Copy, 
  Edit2, History, Loader2, Trash2, Plus, LayoutDashboard, ChevronLeft, ChevronRight, PackagePlus, X, ChevronDown, ChevronUp
} from 'lucide-react';
import clsx from 'clsx';

interface CalculatorViewProps {
  inputs: CalculatorInputs;
  setInputs: React.Dispatch<React.SetStateAction<CalculatorInputs>>;
  results: CalculatedResults;
  history: HistoryItem[];
  editingJobId: string | null;
  isSaving: boolean;
  isSidebarOpen: boolean;
  setIsSidebarOpen: (v: boolean) => void;
  onLoadJob: (job: HistoryItem) => void;
  onEditJob: (job: HistoryItem) => void;
  onDeleteJob: (id: string) => void;
  onSaveJob: (asCopy: boolean) => void;
  onCancel: () => void;
  onShowMath: () => void;
  onShowDashboard: () => void;
  onAddToInventory: () => void;
  handleFile: (file: File) => void;
  isParsing: boolean;
  currency: (val: number) => string;
  onToggleJobStatus?: (job: HistoryItem) => void;
}

export const CalculatorView: React.FC<CalculatorViewProps> = ({
  inputs, setInputs, results, history, editingJobId,
  isSaving, isSidebarOpen, setIsSidebarOpen,
  onLoadJob, onEditJob, onDeleteJob, onSaveJob, onCancel, onShowMath, onShowDashboard, onAddToInventory,
  handleFile, isParsing, currency, onToggleJobStatus
}) => {
  const [dragActive, setDragActive] = useState(false);
  const [viewMode, setViewMode] = useState<'unit' | 'batch'>('unit');

  // Section Visibility State
  const [sections, setSections] = useState({
      overhead: true,
      commercial: true
  });

  // Price Editing State
  const [isEditingPrice, setIsEditingPrice] = useState(false);
  const [priceInputValue, setPriceInputValue] = useState('');

  // --- Handlers ---
  const handleInputChange = (field: keyof CalculatorInputs, value: string | number | boolean) => {
    setInputs(prev => ({ ...prev, [field]: value }));
  };

  const addExtra = () => {
    setInputs(prev => ({ ...prev, extras: [...prev.extras, { id: Date.now().toString(), name: '', price: 0 }] }));
  };

  const updateExtra = (id: string, field: 'name' | 'price', val: string) => {
    setInputs(prev => ({
      ...prev,
      extras: prev.extras.map(ex => ex.id === id ? { ...ex, [field]: val } : ex)
    }));
  };

  const removeExtra = (id: string) => {
    setInputs(prev => ({ ...prev, extras: prev.extras.filter(ex => ex.id !== id) }));
  };

  // --- Reverse Calculation Handler (VAT Inclusive) ---
  const handlePriceChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const val = e.target.value;
    setPriceInputValue(val);

    const numericVal = parseFloat(val);
    if (isNaN(numericVal) || numericVal < 0) return;

    // 1. Determine Target Unit Price (Gross)
    const qty = typeof inputs.batchQty === 'number' ? inputs.batchQty : parseFloat(inputs.batchQty as string) || 1;
    const grossPrice = viewMode === 'unit' ? numericVal : numericVal / qty;

    // 2. Op Cost
    const opCost = results.unit.productionCost + results.unit.packaging;
    if (opCost <= 0) return;

    // 3. Calculate Deductions (Tax + Fees)
    const useFees = inputs.usePlatformFees !== false;
    const comm = useFees ? (typeof inputs.platformCommissionFee === 'number' ? inputs.platformCommissionFee : parseFloat(inputs.platformCommissionFee as string) || 0) : 0;
    const svc = useFees ? (typeof inputs.platformServiceFee === 'number' ? inputs.platformServiceFee : parseFloat(inputs.platformServiceFee as string) || 0) : 0;
    const trans = useFees ? (typeof inputs.platformTransactionFee === 'number' ? inputs.platformTransactionFee : parseFloat(inputs.platformTransactionFee as string) || 0) : 0;
    const fixed = useFees ? (typeof inputs.platformFixedFee === 'number' ? inputs.platformFixedFee : parseFloat(inputs.platformFixedFee as string) || 0) : 0;

    const taxRate = typeof inputs.taxRate === 'number' ? inputs.taxRate : parseFloat(inputs.taxRate as string) || 0;

    // Tax Amount = P - P/(1+rate)
    const taxAmount = grossPrice - (grossPrice / (1 + (taxRate/100)));

    // Fees
    const feeAmount = (grossPrice * (comm/100)) + 
                      (grossPrice * (svc/100)) + 
                      ((grossPrice + results.unit.shipping) * (trans/100)) + 
                      fixed;

    // Net Received (Wallet) before Cost
    const netReceived = grossPrice - taxAmount - feeAmount;

    // Implied Profit
    const impliedProfit = netReceived - opCost;

    // Markup Calculation (No rounding to preserve precision)
    const newMarkup = (impliedProfit / opCost) * 100;

    setInputs(prev => ({
        ...prev,
        markup: newMarkup 
    }));
  };

  // --- Drag & Drop ---
  const handleDrag = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    e.stopPropagation();
    if (e.type === 'dragenter' || e.type === 'dragover') {
      setDragActive(true);
    } else if (e.type === 'dragleave') {
      setDragActive(false);
    }
  }, []);

  const handleDrop = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    e.stopPropagation();
    setDragActive(false);
    if (e.dataTransfer.files && e.dataTransfer.files[0]) {
      handleFile(e.dataTransfer.files[0]);
    }
  }, [handleFile]);

  return (
    <div className="flex h-full relative overflow-hidden">

      {/* Sidebar - Collapsible */}
      <div 
        className={clsx(
          "bg-white border-r border-gray-200 flex flex-col transition-all duration-300 z-30 flex-none h-full",
          "fixed md:relative inset-y-0 left-0", // Fix to viewport on mobile, relative on desktop
          isSidebarOpen ? "w-72 shadow-2xl md:shadow-none translate-x-0" : "-translate-x-full md:translate-x-0 md:w-0 md:overflow-hidden"
        )}
      >
        <div className="p-4 bg-gray-50 border-b border-gray-100 flex items-center justify-between flex-none">
            <h3 className="font-bold text-gray-700 text-xs flex items-center gap-2 uppercase tracking-wide">
                <History size={14} /> Recent Jobs
            </h3>
            {/* Close button for mobile */}
            <button className="md:hidden text-gray-400" onClick={() => setIsSidebarOpen(false)}>
               <X size={20} />
            </button>
        </div>
        <div className="flex-1 overflow-y-auto py-2">
            <HistoryPanel 
                items={history} 
                onLoad={onLoadJob} 
                onEdit={onEditJob} 
                onDelete={(item) => onDeleteJob(item.id)}
                onToggleStatus={(item) => onToggleJobStatus && onToggleJobStatus(item)} 
            />
        </div>
      </div>

      {/* Sidebar Toggle - Custom Design */}
      <button
        onClick={() => setIsSidebarOpen(!isSidebarOpen)}
        className={clsx(
            "absolute top-4 z-50 bg-white border border-gray-200 shadow-md h-8 w-6 rounded-r-lg flex items-center justify-center text-gray-400 hover:text-brand-600 transition-all duration-300 cursor-pointer border-l-0 hidden md:flex",
            isSidebarOpen ? "left-72" : "left-0"
        )}
        title={isSidebarOpen ? "Collapse History" : "Expand History"}
      >
        {isSidebarOpen ? <ChevronLeft size={14} /> : <ChevronRight size={14} />}
      </button>

      {/* Mobile Toggle Button (Visible only when sidebar closed on mobile) */}
      <button
        onClick={() => setIsSidebarOpen(true)}
        className={clsx(
            "absolute top-4 left-0 z-20 bg-white border border-gray-200 shadow-md h-8 w-8 rounded-r-lg flex items-center justify-center text-gray-400 hover:text-brand-600 md:hidden",
            isSidebarOpen ? "hidden" : "flex"
        )}
      >
        <History size={16} />
      </button>

      {/* Overlay for mobile when sidebar is open */}
      {isSidebarOpen && (
          <div 
            className="fixed inset-0 bg-black/20 backdrop-blur-sm z-20 md:hidden"
            onClick={() => setIsSidebarOpen(false)}
          />
      )}

      {/* Main Scrollable Content */}
      <div className="flex-1 overflow-y-auto bg-gray-50/50 p-6 md:p-8 mb-16 md:mb-0">
        <div className="max-w-[1600px] mx-auto grid grid-cols-1 xl:grid-cols-12 gap-8">

          {/* LEFT COLUMN: INPUTS */}
          <div className="xl:col-span-8 space-y-6">

            {/* File Drop Zone */}
            <div 
                className={clsx(
                    "border-2 border-dashed rounded-2xl p-6 text-center transition-all cursor-pointer relative group flex flex-col items-center justify-center min-h-[120px]", 
                    dragActive ? "border-brand-500 bg-brand-50" : "border-gray-300 hover:border-brand-400 bg-white"
                )}
                onDragEnter={handleDrag} onDragLeave={handleDrag} onDragOver={handleDrag} onDrop={handleDrop}
                onClick={() => document.getElementById('fileUpload')?.click()}
            >
                <input type="file" id="fileUpload" className="hidden" onChange={(e) => e.target.files && handleFile(e.target.files[0])} accept=".gcode,.txt,.3mf" />
                <div className={clsx("p-3 rounded-full transition-colors mb-2", dragActive ? "bg-brand-100 text-brand-600" : "bg-blue-50 text-blue-500 group-hover:bg-blue-100")}>
                     {isParsing ? <Loader2 className="animate-spin" size={20} /> : <Upload size={20} />}
                </div>
                <div className="text-sm font-bold text-gray-900">Import G-Code / 3MF</div>
                <p className="text-[10px] text-gray-400">Drag file or click to analyze</p>
            </div>

            {/* SECTION 01: JOB SPECIFICATIONS */}
            <Section title="01 // Job Specifications" icon={<Box size={18} className="text-gray-400" />}>
                 <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
                    <div className="md:col-span-2">
                        <InputGroup label="Job Name" placeholder="e.g. Iron Man Helmet" value={inputs.jobName} onChange={(e) => handleInputChange('jobName', e.target.value)} />
                    </div>
                    <div>
                        <InputGroup label="Batch Quantity" type="number" suffix="pcs" value={inputs.batchQty} onChange={(e) => handleInputChange('batchQty', e.target.value)} />
                    </div>
                    <div>
                        <InputGroup label="Filament Used" type="number" suffix="g" value={inputs.materialGrams} onChange={(e) => handleInputChange('materialGrams', e.target.value)} />
                    </div>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
                    <div className="md:col-span-2">
                        <InputGroup label="Material Cost (1kg)" type="number" prefix="₱" value={inputs.materialCost} onChange={(e) => handleInputChange('materialCost', e.target.value)} />
                    </div>
                    <div>
                            <InputGroup label="Print Time (Hrs)" type="number" value={inputs.timeHours} onChange={(e) => handleInputChange('timeHours', e.target.value)} />
                    </div>
                    <div>
                            <InputGroup label="Print Time (Mins)" type="number" value={inputs.timeMinutes} onChange={(e) => handleInputChange('timeMinutes', e.target.value)} />
                    </div>
                </div>

                {/* Notes Field */}
                <div>
                   <label className="block text-xs font-semibold text-gray-500 mb-1.5 uppercase tracking-wide">
                      Job Notes
                   </label>
                   <textarea 
                      className="w-full bg-white border border-gray-200 text-gray-900 text-sm rounded-lg focus:ring-brand-500 focus:border-brand-500 block p-2.5 transition-all"
                      rows={2}
                      placeholder="Add specific details, customer requests, or printing notes..."
                      value={inputs.notes || ''}
                      onChange={(e) => handleInputChange('notes', e.target.value)}
                   />
                </div>

                {/* Drying Time (Yellow Box) */}
                <div className="bg-orange-50/50 rounded-lg border border-orange-100 p-4">
                    <div className="flex justify-between items-center mb-3">
                        <label className="text-xs font-bold text-gray-600 uppercase tracking-wide">Drying Time</label>
                        <label className="flex items-center gap-2 cursor-pointer select-none">
                            <input 
                                type="checkbox" 
                                className="w-4 h-4 text-brand-600 rounded border-gray-300 focus:ring-brand-500"
                                checked={inputs.dryingTimeSameAsPrintTime}
                                onChange={(e) => handleInputChange('dryingTimeSameAsPrintTime', e.target.checked)}
                            />
                            <span className="text-[10px] font-bold text-brand-600 uppercase tracking-wide">Sync with Print Time</span>
                        </label>
                    </div>
                    <div className="grid grid-cols-2 gap-4">
                            <InputGroup 
                            label="" 
                            type="number" 
                            suffix="hrs" 
                            className={clsx("mb-0 bg-white", inputs.dryingTimeSameAsPrintTime && "opacity-50 pointer-events-none bg-gray-100")}
                            value={inputs.dryingTimeSameAsPrintTime ? inputs.timeHours : inputs.dryingHours} 
                            onChange={(e) => handleInputChange('dryingHours', e.target.value)} 
                            placeholder="0"
                            />
                            <InputGroup 
                            label="" 
                            type="number" 
                            suffix="min" 
                            className={clsx("mb-0 bg-white", inputs.dryingTimeSameAsPrintTime && "opacity-50 pointer-events-none bg-gray-100")}
                            value={inputs.dryingTimeSameAsPrintTime ? inputs.timeMinutes : inputs.dryingMinutes} 
                            onChange={(e) => handleInputChange('dryingMinutes', e.target.value)} 
                            placeholder="0"
                            />
                    </div>
                </div>

                {/* Extras */}
                <div className="bg-gray-50 rounded-lg p-4 border border-gray-200">
                    <div className="flex justify-between items-center mb-3">
                        <span className="text-xs font-bold text-gray-500 uppercase tracking-wider">Hardware & Extras</span>
                        <button onClick={addExtra} className="text-[10px] text-brand-600 font-bold hover:bg-brand-50 px-2 py-1 rounded border border-transparent hover:border-brand-200 transition-colors flex items-center gap-1">
                            <Plus size={12} /> Add Item
                        </button>
                    </div>
                    <div className="space-y-2">
                        {inputs.extras.map((extra) => (
                            <div key={extra.id} className="flex gap-3 animate-in fade-in slide-in-from-top-1 duration-200">
                                <input 
                                    className="flex-1 text-sm border-gray-300 rounded-md px-3 py-2 focus:ring-brand-500 focus:border-brand-500" 
                                    value={extra.name} 
                                    onChange={(e) => updateExtra(extra.id, 'name', e.target.value)} 
                                    placeholder="Item name (e.g. Magnets)" 
                                />
                                <div className="relative w-32">
                                    <span className="absolute left-3 top-2 text-gray-400 text-sm">₱</span>
                                    <input 
                                        className="w-full text-sm border-gray-300 rounded-md pl-7 pr-3 py-2 focus:ring-brand-500 focus:border-brand-500" 
                                        type="number" 
                                        value={extra.price} 
                                        onChange={(e) => updateExtra(extra.id, 'price', e.target.value)} 
                                        placeholder="0.00" 
                                    />
                                </div>
                                <button onClick={() => removeExtra(extra.id)} className="text-gray-400 hover:text-red-500 p-2 hover:bg-red-50 rounded-md transition-colors">
                                    <Trash2 size={16}/>
                                </button>
                            </div>
                        ))}
                        {inputs.extras.length === 0 && (
                            <p className="text-xs text-gray-400 italic text-center py-2">No extras added</p>
                        )}
                    </div>
                </div>
            </Section>

            {/* SECTION 02: FACTORY OVERHEAD */}
            <Section 
                title="02 // Factory Overhead" 
                icon={<Zap size={18} className="text-gray-400" />}
                isOpen={sections.overhead}
                onToggle={() => setSections(prev => ({ ...prev, overhead: !prev.overhead }))}
            >
                <div className="grid grid-cols-2 md:grid-cols-4 gap-6">
                    <InputGroup label="Machine Cost" prefix="₱" value={inputs.machineCost} onChange={(e) => handleInputChange('machineCost', e.target.value)} />
                    <InputGroup label="Lifespan" suffix="hrs" value={inputs.lifespanHours} onChange={(e) => handleInputChange('lifespanHours', e.target.value)} />
                    <InputGroup label="Power Draw" suffix="W" value={inputs.powerWatts} onChange={(e) => handleInputChange('powerWatts', e.target.value)} />
                    <InputGroup label="Dryer Power" suffix="W" value={inputs.dryerPowerWatts} onChange={(e) => handleInputChange('dryerPowerWatts', e.target.value)} />

                    <InputGroup label="Elec. Rate" prefix="₱" suffix="/kWh" value={inputs.elecRate} onChange={(e) => handleInputChange('elecRate', e.target.value)} />
                    <InputGroup label="Labor Rate" prefix="₱" suffix="/hr" value={inputs.laborRate} onChange={(e) => handleInputChange('laborRate', e.target.value)} />
                    <InputGroup label="Prep Time" suffix="min" value={inputs.laborMins} onChange={(e) => handleInputChange('laborMins', e.target.value)} />
                </div>
            </Section>

