        onClick={onClick}
        className={clsx(
            "pb-3 text-sm font-bold border-b-2 transition-colors px-1",
            active ? "border-brand-600 text-brand-600" : "border-transparent text-gray-500 hover:text-gray-700 hover:border-gray-300"
