import React, { useState, useMemo } from 'react';
import { Product } from '../types';
import { Plus, Trash2, Package, Search, Edit2, ArrowUp, ArrowDown, Minus } from 'lucide-react';
import clsx from 'clsx';

interface ProductManagerProps {
  products: Product[];
  onAdd: (p: Omit<Product, 'id'>) => Promise<void>;
  onUpdate: (id: string, p: Partial<Product>) => Promise<void>;
  onDelete: (id: string) => void;
  currency: (val: number) => string;
}

type SortKey = 'name' | 'stock' | 'cost' | 'price' | 'profit' | 'owner';
interface SortConfig {
    key: SortKey;
    direction: 'asc' | 'desc';
}

export const ProductManager: React.FC<ProductManagerProps> = ({ products, onAdd, onUpdate, onDelete, currency }) => {
  const [isAdding, setIsAdding] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');
  const [editingId, setEditingId] = useState<string | null>(null);

  // Sorting State
  const [sortConfig, setSortConfig] = useState<SortConfig>({ key: 'name', direction: 'asc' });

  // Form State
  const [newName, setNewName] = useState('');
  const [newOwner, setNewOwner] = useState('Baz');
  const [newPrice, setNewPrice] = useState('');
  const [newCost, setNewCost] = useState('');
  const [newLabor, setNewLabor] = useState('');
  const [newEnergy, setNewEnergy] = useState('');
  const [newStock, setNewStock] = useState('');
  const [newCategory, setNewCategory] = useState('Standard');
  const [newTaxRate, setNewTaxRate] = useState('12');

  const resetForm = () => {
    setIsAdding(false);
    setEditingId(null);
    setNewName('');
    setNewOwner('Baz');
    setNewPrice('');
    setNewCost('');
    setNewLabor('');
    setNewEnergy('');
    setNewStock('');
    setNewCategory('Standard');
    setNewTaxRate('12');
  };

  const handleEdit = (p: Product) => {
    setEditingId(p.id);
    setNewName(p.name);
    setNewOwner(p.owner || 'Baz');
    // Round to 2 decimals for cleaner editing
    setNewPrice(p.price.toFixed(2));
    setNewCost(p.cost.toFixed(2));
    setNewLabor((p.laborCost || 0).toFixed(2));
    setNewEnergy((p.energyCost || 0).toFixed(2));
    setNewStock(p.stock.toString());
    setNewCategory(p.category);
    setNewTaxRate(p.taxRate !== undefined ? p.taxRate.toString() : '12');
    setIsAdding(true);
  };

  const handleUpdateStock = async (id: string, currentStock: number, delta: number) => {
      const newStock = Math.max(0, currentStock + delta);
      await onUpdate(id, { stock: newStock });
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newName || !newPrice) return;

    const productData = {
      name: newName,
      owner: newOwner,
      price: parseFloat(newPrice),
      cost: parseFloat(newCost) || 0,
      laborCost: parseFloat(newLabor) || 0,
      energyCost: parseFloat(newEnergy) || 0,
      stock: parseInt(newStock) || 0,
      category: newCategory,
      taxRate: parseFloat(newTaxRate) || 0
    };

    if (editingId) {
        await onUpdate(editingId, productData);
    } else {
        await onAdd({
            ...productData,
            createdAt: Date.now()
        });
    }

    resetForm();
  };

  const handleSort = (key: SortKey) => {
      setSortConfig(current => ({
          key,
          direction: current.key === key && current.direction === 'asc' ? 'desc' : 'asc'
      }));
  };

  const processedProducts = useMemo(() => {
    let result = products.filter(p => p.name.toLowerCase().includes(searchTerm.toLowerCase()));

    result.sort((a, b) => {
        const rateA = (a.taxRate !== undefined) ? a.taxRate : 0;
        const netPriceA = a.price / (1 + (rateA/100));
        const profitA = netPriceA - a.cost;

        const rateB = (b.taxRate !== undefined) ? b.taxRate : 0;
        const netPriceB = b.price / (1 + (rateB/100));
        const profitB = netPriceB - b.cost;

        let valA: any = a[sortConfig.key as keyof Product];
        let valB: any = b[sortConfig.key as keyof Product];

        // Handle computed keys
        if (sortConfig.key === 'profit') {
            valA = profitA;
            valB = profitB;
        }

        if (typeof valA === 'string') {
            valA = valA.toLowerCase();
            valB = valB.toLowerCase();
        }

        if (valA < valB) return sortConfig.direction === 'asc' ? -1 : 1;
        if (valA > valB) return sortConfig.direction === 'asc' ? 1 : -1;
        return 0;
    });

    return result;
  }, [products, searchTerm, sortConfig]);

  // Live calculation for form
  const formPrice = parseFloat(newPrice) || 0;
  const formCost = parseFloat(newCost) || 0;
  const formTax = parseFloat(newTaxRate) || 0;
  const formNet = formPrice / (1 + (formTax/100));
  const formProfit = formNet - formCost;
  const formMargin = formNet > 0 ? (formProfit/formNet)*100 : 0;

  const SortHeader = ({ label, sKey, align = 'left' }: { label: string, sKey: SortKey, align?: string }) => (
      <th 
        className={`px-6 py-3 text-xs font-bold text-gray-500 uppercase cursor-pointer hover:text-brand-600 hover:bg-gray-100 transition-colors text-${align}`}
        onClick={() => handleSort(sKey)}
      >
          <div className={`flex items-center gap-1 ${align === 'right' ? 'justify-end' : align === 'center' ? 'justify-center' : 'justify-start'}`}>
            {label}
            {sortConfig.key === sKey && (
                sortConfig.direction === 'asc' ? <ArrowUp size={12}/> : <ArrowDown size={12}/>
            )}
          </div>
      </th>
  );

  return (
    <div className="max-w-6xl mx-auto p-4 md:p-6 mb-16 md:mb-0">

      <div className="flex justify-between items-center mb-6">
        <div>
           <h2 className="text-xl md:text-2xl font-bold text-gray-900 flex items-center gap-2">
            <Package className="text-brand-600" /> Product Inventory
           </h2>
           <p className="text-gray-500 text-xs md:text-sm mt-1">Manage standardized items for Point of Sale.</p>
        </div>
        <button 
          onClick={() => { resetForm(); setIsAdding(true); }}
          className="bg-brand-600 hover:bg-brand-700 text-white px-3 py-2 md:px-4 md:py-2 rounded-lg font-bold flex items-center gap-2 text-xs md:text-sm shadow-lg shadow-brand-500/20"
        >
          <Plus size={16} /> <span className="hidden md:inline">Add Product</span><span className="md:hidden">Add</span>
        </button>
      </div>

      {/* Add/Edit Modal/Panel */}
      {isAdding && (
        <div className="mb-8 bg-white p-6 rounded-xl border border-brand-100 shadow-sm animate-in slide-in-from-top-4">
           <div className="flex justify-between items-start mb-4">
               <h3 className="text-sm font-bold text-gray-900 uppercase tracking-wide">
                   {editingId ? 'Edit Product Details' : 'New Product Details'}
               </h3>
               {/* Live Profit Preview */}
               <div className="bg-gray-50 rounded px-3 py-1 text-right border border-gray-100">
                   <div className="text-[10px] text-gray-500 uppercase">Projected Profit</div>
                   <div className="text-sm font-bold text-brand-600">{currency(formProfit)} ({formMargin.toFixed(0)}%)</div>
               </div>
           </div>

           <form onSubmit={handleSubmit} className="grid grid-cols-1 md:grid-cols-6 gap-4 items-end">
              <div className="md:col-span-2">
                 <label className="block text-xs font-bold text-gray-500 mb-1">Item Name</label>
                 <input autoFocus className="w-full text-sm border-gray-300 rounded-lg p-2.5 focus:ring-brand-500" placeholder="e.g. 3D Benchy - Red" value={newName} onChange={e => setNewName(e.target.value)} required />
              </div>
               <div className="md:col-span-2 grid grid-cols-2 gap-4">
                 <div>
                    <label className="block text-xs font-bold text-gray-500 mb-1">Selling Price</label>
                    <input type="number" step="0.01" className="w-full text-sm border-gray-300 rounded-lg p-2.5 focus:ring-brand-500" placeholder="0.00" value={newPrice} onChange={e => setNewPrice(e.target.value)} required />
                 </div>
                 <div>
                    <label className="block text-xs font-bold text-gray-500 mb-1">VAT Rate %</label>
                    <input type="number" step="0.1" className="w-full text-sm border-gray-300 rounded-lg p-2.5 focus:ring-brand-500" placeholder="12" value={newTaxRate} onChange={e => setNewTaxRate(e.target.value)} />
                 </div>
              </div>
              <div className="grid grid-cols-2 gap-4 md:col-span-2">
                <div>
                    <label className="block text-xs font-bold text-gray-500 mb-1">Stock</label>
                    <input type="number" className="w-full text-sm border-gray-300 rounded-lg p-2.5 focus:ring-brand-500" placeholder="0" value={newStock} onChange={e => setNewStock(e.target.value)} />
                </div>
                <div>
                     <label className="block text-xs font-bold text-gray-500 mb-1">Owner</label>
                     <input list="owner-list" className="w-full text-sm border-gray-300 rounded-lg p-2.5 focus:ring-brand-500" placeholder="Owner" value={newOwner} onChange={e => setNewOwner(e.target.value)} />
                     <datalist id="owner-list">
                         <option value="Baz" />
                         <option value="Ranz" />
                         <option value="Other" />
                     </datalist>
                </div>
              </div>

              <div className="md:col-span-6 grid grid-cols-3 gap-4 border-t border-gray-100 pt-4 mt-2">
                 <div>
                    <label className="block text-xs font-bold text-gray-500 mb-1">Total Cost Basis</label>
                    <input type="number" step="0.01" className="w-full text-sm border-gray-300 rounded-lg p-2.5 focus:ring-brand-500" placeholder="0.00" value={newCost} onChange={e => setNewCost(e.target.value)} />
                    <p className="text-[10px] text-gray-400 mt-1">Material + Operations</p>
                 </div>
                 <div>
                    <label className="block text-xs font-bold text-gray-500 mb-1">Allocated Labor</label>
                    <input type="number" step="0.01" className="w-full text-sm border-gray-300 rounded-lg p-2.5 focus:ring-brand-500" placeholder="0.00" value={newLabor} onChange={e => setNewLabor(e.target.value)} />
                    <p className="text-[10px] text-gray-400 mt-1">For stats tracking</p>
                 </div>
                 <div>
                    <label className="block text-xs font-bold text-gray-500 mb-1">Energy Cost</label>
                    <input type="number" step="0.01" className="w-full text-sm border-gray-300 rounded-lg p-2.5 focus:ring-brand-500" placeholder="0.00" value={newEnergy} onChange={e => setNewEnergy(e.target.value)} />
                    <p className="text-[10px] text-gray-400 mt-1">For stats tracking</p>
                 </div>
              </div>

              <div className="md:col-span-6 flex justify-end gap-2 mt-2">
                 <button type="button" onClick={resetForm} className="px-4 py-2 text-sm font-medium text-gray-600 hover:bg-gray-100 rounded-lg">Cancel</button>
                 <button type="submit" className="px-6 py-2 text-sm font-bold text-white bg-brand-600 hover:bg-brand-700 rounded-lg">
                     {editingId ? 'Update Item' : 'Save Item'}
                 </button>
              </div>
           </form>
        </div>
      )}

      {/* Filter */}
      <div className="relative mb-4">
        <Search className="absolute left-3 top-2.5 text-gray-400" size={18} />
        <input 
          className="w-full pl-10 pr-4 py-2.5 border border-gray-200 rounded-xl text-sm focus:ring-2 focus:ring-brand-500 focus:border-brand-500"
          placeholder="Search products by name..."
          value={searchTerm}
          onChange={e => setSearchTerm(e.target.value)}
        />
      </div>

      {/* Table */}
      <div className="bg-white rounded-xl border border-gray-200 shadow-sm overflow-hidden overflow-x-auto">
        <table className="w-full text-left min-w-[800px]">
          <thead className="bg-gray-50 border-b border-gray-100">
             <tr>
               <SortHeader label="Product" sKey="name" />
               <SortHeader label="Owner" sKey="owner" />
               <SortHeader label="Stock" sKey="stock" align="center" />
               <SortHeader label="Cost" sKey="cost" align="right" />
               <SortHeader label="Price (Inc)" sKey="price" align="right" />
               <SortHeader label="Profit" sKey="profit" align="right" />
               <th className="px-6 py-3 text-xs font-bold text-gray-500 uppercase text-right">Actions</th>
             </tr>
          </thead>
          <tbody className="divide-y divide-gray-100">
             {processedProducts.map(p => {
               const rate = (p.taxRate !== undefined && p.taxRate !== null) ? p.taxRate : 0;
               const netPrice = p.price / (1 + (rate/100));
               const profit = netPrice - p.cost;
               const margin = netPrice > 0 ? (profit / netPrice) * 100 : 0;

               return (
               <tr key={p.id} className={clsx("hover:bg-gray-50 group transition-all", p.stock <= 0 && "opacity-60 grayscale bg-gray-50/50")}>
                 <td className="px-6 py-4">
                    <div className="font-medium text-gray-900">{p.name}</div>
                    <div className="text-xs text-gray-500">{p.category} {rate > 0 ? `• VAT ${rate}%` : ''}</div>
                 </td>
                 <td className="px-6 py-4 text-sm text-gray-600">
                    <span className="bg-gray-100 px-2 py-0.5 rounded font-bold text-xs">{p.owner || '-'}</span>
                 </td>
                 <td className="px-6 py-4 text-center">
                    <div className="flex items-center justify-center gap-2">
                        <button 
                            onClick={() => handleUpdateStock(p.id, p.stock, -1)}
                            className="p-1 text-gray-400 hover:text-red-500 hover:bg-red-50 rounded"
                        >
                            <Minus size={12} />
                        </button>
                        <span className={clsx("px-2 py-1 rounded text-xs font-bold w-8 text-center", p.stock > 0 ? "bg-green-100 text-green-700" : "bg-red-100 text-red-700")}>
                          {p.stock}
                        </span>
                        <button 
                             onClick={() => handleUpdateStock(p.id, p.stock, 1)}
                             className="p-1 text-gray-400 hover:text-green-500 hover:bg-green-50 rounded"
                        >
                            <Plus size={12} />
                        </button>
                    </div>
                 </td>
                 <td className="px-6 py-4 text-right text-sm text-gray-500">{currency(p.cost)}</td>
                 <td className="px-6 py-4 text-right text-sm font-bold text-gray-900">{currency(p.price)}</td>
                 <td className="px-6 py-4 text-right">
                    <div className="text-sm font-bold text-brand-600">{currency(profit)}</div>
                    <div className="text-[10px] text-gray-400">{margin.toFixed(0)}% margin</div>
                 </td>
                 <td className="px-6 py-4 text-right">
                    <div className="flex justify-end gap-1 opacity-100 md:opacity-0 group-hover:opacity-100 transition-opacity">
                        <button onClick={() => handleEdit(p)} className="text-gray-400 hover:text-brand-600 p-1.5 hover:bg-brand-50 rounded">
                           <Edit2 size={16} />
                        </button>
                        <button onClick={() => onDelete(p.id)} className="text-gray-400 hover:text-red-600 p-1.5 hover:bg-red-50 rounded">
                           <Trash2 size={16} />
                        </button>
                    </div>
                 </td>
               </tr>
             )})}
             {processedProducts.length === 0 && (
               <tr><td colSpan={7} className="px-6 py-12 text-center text-gray-400">No products found.</td></tr>
             )}
          </tbody>
        </table>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { Product, HistoryItem, SaleItem, Sale } from '../types';
import { ShoppingCart, Plus, Minus, Trash2, Search, FileText, Package, CreditCard, Banknote, Truck, ArrowRight, Grid, User } from 'lucide-react';
import clsx from 'clsx';

interface POSInterfaceProps {
  products: Product[];
  jobs: HistoryItem[];
  cart: SaleItem[];
  currency: (val: number) => string;
  onAddToCart: (item: SaleItem) => void;
  onUpdateCartQty: (index: number, delta: number) => void;
  onRemoveFromCart: (index: number) => void;
  onCheckout: (paymentMethod: Sale['paymentMethod'], shipping: number, owner: string) => Promise<void>;
  onClearCart: () => void;
}

export const POSInterface: React.FC<POSInterfaceProps> = ({ 
  products, jobs, cart, currency, 
  onAddToCart, onUpdateCartQty, onRemoveFromCart, onCheckout, onClearCart
}) => {
  const [activeTab, setActiveTab] = useState<'products' | 'jobs'>('products');
  const [mobileView, setMobileView] = useState<'catalog' | 'cart'>('catalog'); // Mobile View Toggle
  const [searchTerm, setSearchTerm] = useState('');
  const [paymentModalOpen, setPaymentModalOpen] = useState(false);
  const [shipping, setShipping] = useState<string>(''); 
  const [saleOwner, setSaleOwner] = useState('Baz');

  // Cart Totals
  const subtotal = cart.reduce((sum, item) => sum + (item.unitPrice * item.quantity), 0);
  const shippingCost = parseFloat(shipping) || 0;
  const cartItemCount = cart.reduce((sum, item) => sum + item.quantity, 0);

  // Tax Total for display (optional)
  const totalTax = cart.reduce((sum, item) => {
      const rate = item.taxRate || 0;
      const netPrice = item.unitPrice / (1 + (rate/100));
      return sum + ((item.unitPrice - netPrice) * item.quantity);
  }, 0);

  const finalTotal = subtotal + shippingCost;

  // Filtering
  const filteredProducts = products.filter(p => p.name.toLowerCase().includes(searchTerm.toLowerCase()));
  const filteredJobs = jobs.filter(j => j.name.toLowerCase().includes(searchTerm.toLowerCase()));

  const handleProductClick = (p: Product) => {
    // Check stock limit
    const existingItem = cart.find(i => i.refId === p.id && i.type === 'product');
    const currentQty = existingItem ? existingItem.quantity : 0;

    if (currentQty >= p.stock) {
        return; // Do nothing if stock exhausted
    }

    onAddToCart({
      type: 'product',
      refId: p.id,
      name: p.name,
      quantity: 1,
      unitPrice: p.price,
      unitCost: p.cost,
      laborCost: p.laborCost || 0, // Pass labor cost, default to 0
      energyCost: p.energyCost || 0, // Pass energy cost, default to 0
      taxRate: p.taxRate || 0
    });
  };

  const handleJobClick = (j: HistoryItem) => {
    // Attempt to extract tax rate from job inputs
    let tax = 0;
    if (j.inputs && j.inputs.taxRate) {
        tax = typeof j.inputs.taxRate === 'number' ? j.inputs.taxRate : parseFloat(j.inputs.taxRate as string);
    }

    // Extract Labor & Energy from snapshot if available
    const labor = j.resultsSnapshot?.unit.labor;
    // Energy cost usually includes depreciation in "machine time" context, but strictly energy is energy.
    // Let's pass the raw energy value from snapshot.
    const energy = j.resultsSnapshot?.unit.energy;

    onAddToCart({
      type: 'job',
      refId: j.id,
      name: j.name,
      quantity: typeof j.inputs.batchQty === 'string' ? parseFloat(j.inputs.batchQty) : j.inputs.batchQty,
      unitPrice: j.resultsSnapshot?.unit.finalPrice || 0,
      unitCost: j.resultsSnapshot?.unit.productionCost || 0,
      laborCost: labor || 0,
      energyCost: energy || 0,
      taxRate: tax || 0
    });
  };

  const handleQtyChange = (index: number, delta: number) => {
      const item = cart[index];
      if (item.type === 'product' && delta > 0) {
          const product = products.find(p => p.id === item.refId);
          if (product && item.quantity >= product.stock) {
              return; // Limit reached
          }
      }
      onUpdateCartQty(index, delta);
  };

  const handlePayment = (method: Sale['paymentMethod']) => {
      onCheckout(method, shippingCost, saleOwner);
      setPaymentModalOpen(false);
      setShipping(''); // Reset shipping after checkout
      setMobileView('catalog'); // Return to catalog
  };

  return (
    <div className="flex flex-col md:flex-row h-[calc(100vh-64px)] md:h-[calc(100vh-64px)] overflow-hidden relative">

      {/* LEFT PANEL: CATALOG */}
      <div className={clsx(
          "flex-1 flex flex-col bg-gray-50 border-r border-gray-200 h-full",
          mobileView === 'cart' ? 'hidden md:flex' : 'flex'
      )}>
        {/* Search & Tabs */}
        <div className="p-4 bg-white border-b border-gray-200 shadow-sm z-10">
          <div className="flex gap-2 mb-4">
             <button 
                onClick={() => setActiveTab('products')}
                className={`flex-1 py-2 text-sm font-bold rounded-lg flex items-center justify-center gap-2 transition-colors ${activeTab === 'products' ? 'bg-brand-600 text-white' : 'bg-gray-100 text-gray-600 hover:bg-gray-200'}`}
             >
               <Package size={16} /> Products
             </button>
             <button 
                onClick={() => setActiveTab('jobs')}
                className={`flex-1 py-2 text-sm font-bold rounded-lg flex items-center justify-center gap-2 transition-colors ${activeTab === 'jobs' ? 'bg-brand-600 text-white' : 'bg-gray-100 text-gray-600 hover:bg-gray-200'}`}
             >
               <FileText size={16} /> Saved Jobs
             </button>
          </div>
          <div className="relative">
            <Search className="absolute left-3 top-2.5 text-gray-400" size={18} />
            <input 
              className="w-full pl-10 pr-4 py-2 border border-gray-200 rounded-lg text-sm focus:ring-2 focus:ring-brand-500"
              placeholder="Search items..."
              value={searchTerm}
              onChange={e => setSearchTerm(e.target.value)}
            />
          </div>
        </div>

        {/* Grid/List Content */}
        <div className="flex-1 overflow-y-auto p-4 pb-20 md:pb-4">
          {activeTab === 'products' ? (
             <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-3">
               {filteredProducts.map(p => {
                 const inCart = cart.find(i => i.refId === p.id && i.type === 'product')?.quantity || 0;
                 const isOutOfStock = p.stock <= 0 || inCart >= p.stock;

                 return (
                    <div 
                        key={p.id} 
                        onClick={() => !isOutOfStock && handleProductClick(p)}
                        className={clsx(
                            "bg-white p-3 rounded-xl border border-gray-200 shadow-sm transition-all flex flex-col justify-between h-32",
                            isOutOfStock ? "opacity-50 grayscale cursor-not-allowed bg-gray-50" : "hover:border-brand-500 hover:shadow-md cursor-pointer"
                        )}
                    >
                        <div>
                        <h4 className="font-bold text-gray-800 text-sm line-clamp-2">{p.name}</h4>
                        <p className={clsx("text-xs mt-1", p.stock === 0 ? "text-red-500 font-bold" : "text-gray-500")}>
                            {p.stock === 0 ? "Out of Stock" : `${p.stock} in stock`}
                        </p>
                        </div>
                        <div className="flex justify-between items-end">
                            <div className="font-bold text-brand-600 text-lg">{currency(p.price)}</div>
                            {p.taxRate > 0 && <span className="text-[10px] text-gray-400">VAT {p.taxRate}%</span>}
                        </div>
                    </div>
                 );
               })}
             </div>
          ) : (
             <div className="space-y-2">
               {filteredJobs.map(j => (
                 <div 
                    key={j.id} 
                    onClick={() => handleJobClick(j)}
                    className="bg-white p-3 rounded-xl border border-gray-200 shadow-sm hover:border-brand-500 hover:shadow-md cursor-pointer transition-all flex justify-between items-center"
                 >
                    <div>
                      <h4 className="font-bold text-gray-800 text-sm">{j.name}</h4>
                      <p className="text-xs text-gray-500">{j.date}</p>
                    </div>
                    <div className="text-right">
                       <div className="font-bold text-brand-600">{currency(j.resultsSnapshot?.unit.finalPrice || 0)}</div>
                       <div className="text-xs text-gray-400">per unit</div>
                    </div>
                 </div>
               ))}
             </div>
          )}
        </div>

        {/* Mobile View Cart Button */}
        <div className="md:hidden absolute bottom-4 right-4 z-20">
             <button 
                onClick={() => setMobileView('cart')}
                className="bg-brand-600 text-white p-4 rounded-full shadow-lg flex items-center gap-2 relative"
             >
                 <ShoppingCart size={24} />
                 {cartItemCount > 0 && (
                     <span className="absolute -top-2 -right-2 bg-red-500 text-white text-xs font-bold w-6 h-6 rounded-full flex items-center justify-center">
                         {cartItemCount}
                     </span>
                 )}
             </button>
        </div>
      </div>

      {/* RIGHT PANEL: CART */}
      <div className={clsx(
          "w-full md:w-96 flex-col bg-white shadow-xl z-20 h-full",
          mobileView === 'cart' ? 'flex' : 'hidden md:flex'
      )}>
         <div className="p-4 bg-gray-900 text-white flex justify-between items-center">
            <div className="flex items-center gap-2">
                <button onClick={() => setMobileView('catalog')} className="md:hidden text-gray-400 hover:text-white">
                    <ArrowRight className="rotate-180" size={20} />
                </button>
                <h2 className="font-bold flex items-center gap-2"><ShoppingCart size={20} /> Current Sale</h2>
            </div>
            <button onClick={onClearCart} className="text-xs text-gray-400 hover:text-white">Clear</button>
         </div>

         <div className="flex-1 overflow-y-auto p-4 space-y-3">
            {cart.map((item, idx) => {
                const product = item.type === 'product' ? products.find(p => p.id === item.refId) : null;
                const isMax = product ? item.quantity >= product.stock : false;

                return (
                    <div key={idx} className="flex gap-2 items-center bg-gray-50 p-2 rounded-lg border border-gray-100">
                        <div className="flex-1">
                            <h4 className="text-sm font-bold text-gray-800 line-clamp-1">{item.name}</h4>
                            <div className="flex justify-between items-center pr-2">
                                <div className="text-xs text-brand-600 font-bold">{currency(item.unitPrice)}</div>
                                {item.taxRate > 0 && <span className="text-[9px] text-gray-400">Inc {item.taxRate}% Tax</span>}
                            </div>
                        </div>
                        <div className="flex items-center gap-2 bg-white border border-gray-200 rounded px-1 shadow-sm">
                            <button onClick={() => handleQtyChange(idx, -1)} className="p-1 text-gray-500 hover:text-red-600 transition-colors"><Minus size={12}/></button>
                            <span className="text-xs font-bold w-6 text-center text-gray-800 select-none">{item.quantity}</span>
                            <button 
                                onClick={() => handleQtyChange(idx, 1)} 
                                disabled={isMax}
                                className={clsx("p-1 transition-colors", isMax ? "text-gray-300 cursor-not-allowed" : "text-gray-500 hover:text-green-600")}
                            >
                                <Plus size={12}/>
                            </button>
                        </div>
                        <button onClick={() => onRemoveFromCart(idx)} className="text-gray-400 hover:text-red-500 p-1"><Trash2 size={16} /></button>
                    </div>
                );
            })}
            {cart.length === 0 && (
              <div className="text-center py-10 text-gray-400 text-sm italic">
                Cart is empty. Select items from the catalog.
              </div>
            )}
         </div>

         <div className="p-4 border-t border-gray-200 bg-gray-50 mb-16 md:mb-0">

            <div className="flex justify-between items-center mb-1 text-gray-500 text-xs">
               <span className="flex items-center gap-1"><User size={12}/> Sold By (Owner)</span>
               <div className="flex items-center w-24">
                  <input 
                      list="pos-owners"
                      className="w-full text-right border border-gray-200 rounded px-1 py-0.5 text-xs bg-white focus:ring-1 focus:ring-brand-500 focus:outline-none"
                      placeholder="Owner"
                      value={saleOwner}
                      onChange={e => setSaleOwner(e.target.value)}
                  />
                  <datalist id="pos-owners">
                      <option value="Baz" />
                      <option value="Ranz" />
                      <option value="Other" />
                  </datalist>
               </div>
            </div>

            <div className="flex justify-between items-center mb-1 text-gray-500 text-xs">
               <span>Subtotal (Gross)</span>
               <span>{currency(subtotal)}</span>
            </div>

            <div className="flex justify-between items-center mb-1 text-gray-500 text-xs">
               <span className="flex items-center gap-1"><Truck size={12}/> Shipping</span>
               <div className="flex items-center w-24">
                 <span className="mr-1 text-gray-400">₱</span>
                 <input 
                   type="number" 
                   min="0"
                   step="0.01"
                   className="w-full text-right border border-gray-200 rounded px-1 py-0.5 text-xs bg-white focus:ring-1 focus:ring-brand-500 focus:outline-none"
                   placeholder="0.00"
                   value={shipping}
                   onChange={e => setShipping(e.target.value)}
                 />
               </div>
            </div>

            <div className="flex justify-between items-center mb-4 text-gray-400 text-xs">
               <span>Included VAT/Tax</span>
               <span>{currency(totalTax)}</span>
            </div>

            <div className="flex justify-between items-center mb-4 border-t border-gray-100 pt-2">
               <span className="text-gray-900 font-bold text-lg">Total</span>
               <span className="text-2xl font-black text-gray-900">{currency(finalTotal)}</span>
            </div>

            <button 
              disabled={cart.length === 0}
              onClick={() => setPaymentModalOpen(true)}
              className="w-full bg-brand-600 hover:bg-brand-700 disabled:bg-gray-300 disabled:cursor-not-allowed text-white py-3 rounded-xl font-bold text-lg shadow-lg shadow-brand-500/30 transition-all"
            >
              Checkout
            </button>
         </div>
      </div>

      {/* Payment Modal */}
      {paymentModalOpen && (
        <div className="fixed inset-0 bg-black/60 backdrop-blur-sm z-50 flex items-center justify-center">
           <div className="bg-white rounded-2xl w-full max-w-sm p-6 shadow-2xl animate-in fade-in zoom-in duration-200">
              <h3 className="text-lg font-bold text-gray-900 mb-4 text-center">Select Payment Method</h3>
              <div className="space-y-3">
                 <button onClick={() => handlePayment('cash')} className="w-full flex items-center justify-center gap-3 p-4 border border-gray-200 rounded-xl hover:border-green-500 hover:bg-green-50 font-bold text-gray-700">
                    <Banknote className="text-green-600" /> Cash
                 </button>
                 <button onClick={() => handlePayment('gcash')} className="w-full flex items-center justify-center gap-3 p-4 border border-gray-200 rounded-xl hover:border-blue-500 hover:bg-blue-50 font-bold text-gray-700">
                    <span className="text-blue-600 font-black">G</span> GCash
                 </button>
                 <button onClick={() => handlePayment('card')} className="w-full flex items-center justify-center gap-3 p-4 border border-gray-200 rounded-xl hover:border-purple-500 hover:bg-purple-50 font-bold text-gray-700">
                    <CreditCard className="text-purple-600" /> Card / Other
                 </button>
              </div>
              <button onClick={() => setPaymentModalOpen(false)} className="mt-4 w-full py-2 text-gray-400 hover:text-gray-600 text-sm">Cancel</button>
           </div>
        </div>
      )}

    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { CalculatorInputs, CalculatedResults, HistoryItem, CapitalItem, Product, SaleItem, Sale } from './types';
import { calculateCosts } from './services/calculatorService';
import { parseGCodeFile } from './services/gcodeService';
import { 
  saveJob, getJobs, deleteJob, updateJob,
  saveCapitalItem, getCapitalItems, deleteCapitalItem, updateCapitalItem,
  getProducts, saveProduct, deleteProduct, updateProduct,
  saveSale, getSales, updateSale, deleteSale,
  getSyncStatus
} from './services/firebase';
import { loadSettings, saveSettings, mergeWithDefaults } from './services/settingsService';

// View Components
import { CalculatorView } from './components/CalculatorView';
import { DashboardView } from './components/DashboardView';
import { MathModal } from './components/MathModal';
import { ProductManager } from './components/ProductManager';
import { POSInterface } from './components/POSInterface';
import { ConfirmDialog } from './components/ConfirmDialog';

import { 
  Printer, Calculator, Package as PackageIcon, 
  ShoppingCart, LayoutDashboard, Cloud, Settings, Download, Upload, Loader2, X
} from 'lucide-react';
import clsx from 'clsx';

function App() {
  // --- STATE MANAGEMENT ---
  const [activeView, setActiveView] = useState<'calculator' | 'products' | 'pos' | 'dashboard'>('calculator');

  // Calculator State
  const [inputs, setInputs] = useState<CalculatorInputs>(() => {
    const saved = loadSettings();
    return mergeWithDefaults(saved);
  });
  const [results, setResults] = useState<CalculatedResults>(() => calculateCosts(inputs));
  const [editingJobId, setEditingJobId] = useState<string | null>(null);
  const [isParsing, setIsParsing] = useState(false);
  const [isSaving, setIsSaving] = useState(false);

  // Data State
  const [history, setHistory] = useState<HistoryItem[]>([]);
  const [capitalHistory, setCapitalHistory] = useState<CapitalItem[]>([]);
  const [products, setProducts] = useState<Product[]>([]);
  const [sales, setSales] = useState<Sale[]>([]);
  const [syncStatus] = useState(getSyncStatus());

  // POS State (Lifted)
  const [cart, setCart] = useState<SaleItem[]>([]);

  // UI State
  const [isSidebarOpen, setIsSidebarOpen] = useState(() => {
    if (typeof window !== 'undefined') {
        const saved = localStorage.getItem('bambuCalc_Sidebar');
        return saved !== null ? JSON.parse(saved) : true;
    }
    return true;
  });
  const [showMathModal, setShowMathModal] = useState(false);
  const [showSettingsModal, setShowSettingsModal] = useState(false);

  const [jobToDelete, setJobToDelete] = useState<string | null>(null);
  const [productToDelete, setProductToDelete] = useState<string | null>(null);
  const [saleToDelete, setSaleToDelete] = useState<string | null>(null);
  const [productToImport, setProductToImport] = useState<Omit<Product, 'id' | 'createdAt' | 'stock' | 'category'> | null>(null);
  const [isImporting, setIsImporting] = useState(false);

  // --- EFFECT HOOKS ---

  // Initial Data Load
  const refreshAllData = async () => {
    return Promise.all([
      getJobs(),
      getCapitalItems(),
      getProducts(),
      getSales()
    ]).then(([j, c, p, s]) => {
      setHistory(j);
      setCapitalHistory(c);
      setProducts(p);
      setSales(s);
    });
  };

  useEffect(() => {
    refreshAllData();
  }, []);

  // Recalculate when inputs change
  useEffect(() => {
    setResults(calculateCosts(inputs));
  }, [inputs]);

  // Persist settings
  useEffect(() => {
    saveSettings(inputs);
  }, [inputs]);

  const currency = (val: number) => '₱' + val.toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 });

  // --- HANDLERS ---

  // File Handler
  const handleFile = async (file: File) => {
    setIsParsing(true);
    try {
      const data = await parseGCodeFile(file);
      if (data.found) {
        setInputs(prev => ({
          ...prev,
          timeHours: data.hours,
          timeMinutes: data.minutes,
          materialGrams: data.grams,
          jobName: data.filename?.replace(/\.(gcode|3mf|txt)$/i, '') || prev.jobName
        }));
      } else {
        alert("Could not extract print time or weight from file.");
      }
    } catch (e) {
      console.error(e);
      alert("Error parsing file");
    } finally {
      setIsParsing(false);
    }
  };

  // Job Handlers
  const handleLoadJob = (job: HistoryItem) => {
    setInputs(job.inputs);
    setEditingJobId(job.id);
    setActiveView('calculator');
    if (window.innerWidth < 768) setIsSidebarOpen(false);
  };

  const handleEditJob = (job: HistoryItem) => {
    handleLoadJob(job);
  };

  const handleSaveJob = async (asCopy: boolean) => {
    setIsSaving(true);
    try {
      const jobData = {
        name: inputs.jobName || 'Untitled Job',
        owner: inputs.owner || 'Baz',
        date: new Date().toLocaleDateString(),
        inputs,
        resultsSnapshot: results,
        finalPrice: results.unit.finalPrice,
        status: 'pending' as const,
        createdAt: Date.now()
      };

      if (editingJobId && !asCopy) {
        await updateJob(editingJobId, { ...jobData, updatedAt: Date.now() });
        setEditingJobId(null);
      } else {
        await saveJob(jobData);
      }
      refreshAllData();
    } catch (e) {
      console.error(e);
      alert("Failed to save job");
    } finally {
      setIsSaving(false);
    }
  };

  const handleToggleJobStatus = async (job: HistoryItem) => {
    const newStatus = job.status === 'completed' ? 'pending' : 'completed';
    await updateJob(job.id, { status: newStatus });
    refreshAllData();
  };

  const confirmDeleteJob = async () => {
    if (jobToDelete) {
      await deleteJob(jobToDelete);
      refreshAllData();
      setJobToDelete(null);
    }
  };

  const handleAddToInventory = () => {
      setProductToImport({
          name: inputs.jobName || 'Untitled Print',
          owner: inputs.owner || 'Baz',
          price: results.unit.finalPrice,
          cost: results.unit.productionCost,
          laborCost: results.unit.labor,
          energyCost: results.unit.energy,
          taxRate: typeof inputs.taxRate === 'number' ? inputs.taxRate : parseFloat(inputs.taxRate as string)
      });
      setActiveView('products');
  };

  // Capital Handlers
  const handleAddCapital = async (item: Omit<CapitalItem, 'id'>) => {
    await saveCapitalItem(item);
    refreshAllData();
  };

  const handleUpdateCapital = async (id: string, updates: Partial<CapitalItem>) => {
    await updateCapitalItem(id, updates);
    refreshAllData();
  };

  const confirmDeleteCapital = async (id: string) => {
    await deleteCapitalItem(id);
    refreshAllData();
  };

  // Product Handlers
  const handleAddProduct = async (p: Omit<Product, 'id'>) => {
    await saveProduct(p);
    refreshAllData();
  };

  const handleUpdateProduct = async (id: string, p: Partial<Product>) => {
    await updateProduct(id, p);
    refreshAllData();
  };

  const confirmDeleteProduct = async () => {
    if (productToDelete) {
      await deleteProduct(productToDelete);
      refreshAllData();
      setProductToDelete(null);
    }
  };

  // Sale/POS Handlers
  const handleCheckout = async (paymentMethod: Sale['paymentMethod'], shipping: number, owner: string) => {
    let totalRevenue = 0;
    let totalCost = 0;

    // Calculate totals and deduct stock
    for (const item of cart) {
        totalRevenue += item.unitPrice * item.quantity;
        totalCost += item.unitCost * item.quantity;

        if (item.type === 'product') {
            const product = products.find(p => p.id === item.refId);
            if (product) {
                await updateProduct(product.id, { stock: product.stock - item.quantity });
            }
        }
    }

    const sale: Omit<Sale, 'id'> = {
        items: cart,
        totalRevenue: totalRevenue + shipping,
        totalCost,
        totalProfit: (totalRevenue + shipping) - totalCost,
        paymentMethod,
        owner,
        shipping,
        timestamp: Date.now(),
        dateStr: new Date().toLocaleDateString()
    };

    await saveSale(sale);
    setCart([]);
    refreshAllData();
  };

  const handleUpdateSale = async (id: string, updates: Partial<Sale>) => {
    await updateSale(id, updates);
    refreshAllData();
  };

  const confirmDeleteSale = async () => {
    if (saleToDelete) {
      await deleteSale(saleToDelete);
      refreshAllData();
      setSaleToDelete(null);
    }
  };

  // --- BACKUP / RESTORE LOGIC ---

  const handleExportData = () => {
      const data = {
          jobs: history,
          products: products,
          sales: sales,
          capital: capitalHistory,
          exportedAt: new Date().toISOString()
      };

      const jsonString = JSON.stringify(data, null, 2);
      const blob = new Blob([jsonString], { type: 'application/json' });
      const url = URL.createObjectURL(blob);
      const link = document.createElement('a');
      link.href = url;
      link.download = `3d_print_data_backup_${new Date().toISOString().split('T')[0]}.json`;
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
  };

  const handleImportData = async (e: React.ChangeEvent<HTMLInputElement>) => {
      if (!e.target.files || !e.target.files[0]) return;
      const file = e.target.files[0];

      setIsImporting(true);
      try {
          const text = await file.text();
          const data = JSON.parse(text);

          const [exJobs, exProducts, exSales, exCapital] = await Promise.all([
             getJobs(2000), 
             getProducts(),
             getSales(2000),
             getCapitalItems(2000)
          ]);

          const jobTimestamps = new Set(exJobs.map(j => j.createdAt));
          const productNames = new Set(exProducts.map(p => p.name.toLowerCase()));
          const saleTimestamps = new Set(exSales.map(s => s.timestamp));
          const getCapKey = (c: any) => `${c.name}|${c.purchaseDate}|${c.price}`;
          const capitalKeys = new Set(exCapital.map(c => getCapKey(c)));

          let added = 0;
          let skipped = 0;

          // Import Jobs
          if (data.jobs && Array.isArray(data.jobs)) {
              for (const job of data.jobs) {
                 if (job.createdAt && jobTimestamps.has(job.createdAt)) {
                     skipped++; continue;
                 }
                 const { id, ...rest } = job; 
                 await saveJob(rest);
                 added++;
              }
          }

          // Import Products
          if (data.products && Array.isArray(data.products)) {
              for (const p of data.products) {
                  if (p.name && productNames.has(p.name.toLowerCase())) {
                      skipped++; continue;
                  }
                  const { id, ...rest } = p;
                  await saveProduct(rest);
                  added++;
              }
          }

          // Import Sales
          if (data.sales && Array.isArray(data.sales)) {
              for (const s of data.sales) {
                  if (s.timestamp && saleTimestamps.has(s.timestamp)) {
                      skipped++; continue;
                  }
                  const { id, ...rest } = s;
                  await saveSale(rest);
                  added++;
              }
          }

          // Import Capital
          if (data.capital && Array.isArray(data.capital)) {
              for (const c of data.capital) {
                  const key = getCapKey(c);
                  if (capitalKeys.has(key)) {
                      skipped++; continue;
                  }
                  const { id, ...rest } = c;
                  await saveCapitalItem(rest);
                  added++;
              }
          }

          alert(`Import successful!\n\n✅ Added: ${added} new records\n🚫 Skipped: ${skipped} duplicates`);
          await refreshAllData();
          setShowSettingsModal(false);

      } catch (err) {
          console.error(err);
          alert("Failed to import file. Invalid format or corrupt file.");
      } finally {
          setIsImporting(false);
          // Reset file input
          e.target.value = '';
      }
  };

  // Navigation Helper
  const NavItem = ({ view, icon: Icon, label }: { view: typeof activeView, icon: any, label: string }) => (
    <button 
      onClick={() => setActiveView(view)}
      className={clsx(
          "flex items-center gap-2 px-4 py-2 rounded-lg transition-colors text-sm font-bold",
          activeView === view ? "bg-brand-600 text-white" : "text-gray-600 hover:bg-gray-100"
      )}
    >
        <Icon size={18} />
        <span className="hidden md:inline">{label}</span>
    </button>
  );

  return (
    <div className="flex flex-col h-screen bg-white">
        {/* Top Navigation */}
        <header className="flex items-center justify-between px-6 py-3 border-b border-gray-200 flex-none bg-white z-40">
            <div className="flex items-center gap-3">
                <div className="bg-brand-600 text-white p-2 rounded-lg">
                    <Printer size={20} />
                </div>
                <div>
                    <h1 className="font-black text-lg text-gray-900 leading-none">BambuCalc</h1>
                    <div className="flex items-center gap-1 text-[10px] text-gray-400 font-medium">
                        <Cloud size={10} /> {syncStatus.isCloud ? 'Cloud Sync Active' : 'Local Mode'}
                    </div>
                </div>
            </div>

            <nav className="flex items-center gap-2 bg-gray-50 p-1 rounded-xl border border-gray-100 hidden md:flex">
                <NavItem view="calculator" icon={Calculator} label="Calculator" />
                <NavItem view="products" icon={PackageIcon} label="Inventory" />
                <NavItem view="pos" icon={ShoppingCart} label="POS" />
                <NavItem view="dashboard" icon={LayoutDashboard} label="Dashboard" />
            </nav>

            {/* Mobile Nav Dropdown Placeholder (Simplified for now) */}
            <div className="md:hidden">
               <button onClick={() => setActiveView(activeView === 'calculator' ? 'dashboard' : 'calculator')} className="text-gray-600">
                  <LayoutDashboard />
               </button>
            </div>

            <div className="flex items-center gap-2 md:w-32 justify-end">
                 <button 
                    onClick={() => setShowSettingsModal(true)}
                    className="p-2 text-gray-400 hover:text-gray-900 hover:bg-gray-100 rounded-lg transition-all"
                    title="Settings & Data"
                 >
                    <Settings size={20} />
                 </button>
            </div>
        </header>

        {/* Main View Area */}
        <main className="flex-1 overflow-hidden relative">
            {activeView === 'calculator' && (
                <CalculatorView 
                    inputs={inputs}
                    setInputs={setInputs}
                    results={results}
                    history={history}
                    editingJobId={editingJobId}
                    isSaving={isSaving}
                    isSidebarOpen={isSidebarOpen}
                    setIsSidebarOpen={setIsSidebarOpen}
                    onLoadJob={handleLoadJob}
                    onEditJob={handleEditJob}
                    onDeleteJob={id => setJobToDelete(id)}
                    onSaveJob={handleSaveJob}
                    onCancel={() => { setEditingJobId(null); setInputs(mergeWithDefaults({})); }}
                    onShowMath={() => setShowMathModal(true)}
                    onShowDashboard={() => setActiveView('dashboard')}
                    onAddToInventory={handleAddToInventory}
                    handleFile={handleFile}
                    isParsing={isParsing}
                    currency={currency}
                    onToggleJobStatus={handleToggleJobStatus}
                />
            )}

            {activeView === 'products' && (
                <ProductManager 
                    products={products}
                    onAdd={handleAddProduct}
                    onUpdate={handleUpdateProduct}
                    onDelete={id => setProductToDelete(id)}
                    currency={currency}
                />
            )}

            {activeView === 'pos' && (
                <POSInterface 
                    products={products}
                    jobs={history}
                    cart={cart}
                    currency={currency}
                    onAddToCart={item => {
                        const existing = cart.findIndex(c => c.type === item.type && c.refId === item.refId);
                        if (existing >= 0) {
                            const newCart = [...cart];
                            newCart[existing].quantity += item.quantity;
                            setCart(newCart);
                        } else {
                            setCart([...cart, item]);
                        }
                    }}
                    onUpdateCartQty={(idx, delta) => {
                         const newCart = [...cart];
                         newCart[idx].quantity += delta;
                         if (newCart[idx].quantity <= 0) newCart.splice(idx, 1);
                         setCart(newCart);
                    }}
                    onRemoveFromCart={idx => {
                        const newCart = [...cart];
                        newCart.splice(idx, 1);
                        setCart(newCart);
                    }}
                    onCheckout={handleCheckout}
                    onClearCart={() => setCart([])}
                />
            )}

            {activeView === 'dashboard' && (
                <DashboardView 
                    history={history}
                    capitalHistory={capitalHistory}
                    sales={sales}
                    onDeleteJob={id => setJobToDelete(id)}
                    onAddCapital={handleAddCapital}
                    onUpdateCapital={handleUpdateCapital}
                    onDeleteCapital={confirmDeleteCapital}
                    onUpdateSale={handleUpdateSale}
                    onDeleteSale={id => setSaleToDelete(id)}
                    currency={currency}
                />
            )}
        </main>

        {/* Modals & Dialogs (Unchanged) */}
        <MathModal 
            isOpen={showMathModal} 
            onClose={() => setShowMathModal(false)}
            inputs={inputs}
            results={results}
            currency={currency}
        />

        {showSettingsModal && (
          <div className="fixed inset-0 z-[70] flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm animate-in fade-in duration-200">
             <div className="bg-white rounded-2xl w-full max-w-md p-6 shadow-2xl border border-gray-100">
                 <div className="flex justify-between items-center mb-6">
                    <h2 className="text-lg font-bold text-gray-900 flex items-center gap-2">
                        <Settings className="text-brand-600" /> Settings & Data
                    </h2>
                    <button onClick={() => setShowSettingsModal(false)} className="text-gray-400 hover:text-gray-600">
                        <X size={20} />
                    </button>
                 </div>

                 <div className="space-y-4">
                     <div className="bg-gray-50 p-4 rounded-xl border border-gray-100">
                         <h3 className="text-sm font-bold text-gray-800 mb-2">Backup Data</h3>
                         <p className="text-xs text-gray-500 mb-3">Download a JSON file containing all jobs, products, sales, and expenses.</p>
                         <button 
                            onClick={handleExportData}
                            className="w-full flex items-center justify-center gap-2 bg-white border border-gray-200 hover:border-brand-500 text-gray-700 hover:text-brand-600 font-bold py-2 rounded-lg transition-colors text-sm shadow-sm"
                         >
                             <Download size={16} /> Download Backup
                         </button>
                     </div>

                     <div className="bg-gray-50 p-4 rounded-xl border border-gray-100">
                         <h3 className="text-sm font-bold text-gray-800 mb-2">Restore Data</h3>
                         <p className="text-xs text-gray-500 mb-3">Import data from a backup file. Existing records will be skipped.</p>
                         <div className="relative">
                            <input 
                                type="file" 
                                accept=".json" 
                                onChange={handleImportData}
                                className="absolute inset-0 w-full h-full opacity-0 cursor-pointer"
                                disabled={isImporting}
                            />
                            <button 
                                className="w-full flex items-center justify-center gap-2 bg-brand-600 hover:bg-brand-700 text-white font-bold py-2 rounded-lg transition-colors text-sm shadow-md disabled:opacity-50"
                                disabled={isImporting}
                            >
                                {isImporting ? <Loader2 className="animate-spin" size={16} /> : <Upload size={16} />}
                                {isImporting ? 'Importing...' : 'Upload Backup File'}
                            </button>
                         </div>
                     </div>
                 </div>

                 <div className="mt-6 text-center text-[10px] text-gray-400">
                     v1.3.0 • Cloud Sync Active
                 </div>
             </div>
          </div>
        )}

        <ConfirmDialog 
            isOpen={!!jobToDelete}
            title="Delete Job?"
            message="This action cannot be undone."
            onConfirm={confirmDeleteJob}
            onCancel={() => setJobToDelete(null)}
        />

        <ConfirmDialog 
            isOpen={!!productToDelete}
            title="Delete Product?"
            message="Are you sure? This will remove the product from inventory and POS."
            onConfirm={confirmDeleteProduct}
            onCancel={() => setProductToDelete(null)}
        />

        <ConfirmDialog 
            isOpen={!!saleToDelete}
            title="Delete Sale Record?"
            message="This will remove the transaction from your ledger."
            onConfirm={confirmDeleteSale}
            onCancel={() => setSaleToDelete(null)}
        />

        <ConfirmDialog 
            isOpen={!!productToImport}
            title="Import to Inventory"
            message={`Add "${productToImport?.name}" to Inventory?\nRecommended Price: ${currency(productToImport?.price || 0)}\nCost Basis: ${currency(productToImport?.cost || 0)}\nLabor: ${currency(productToImport?.laborCost || 0)}\nEnergy: ${currency(productToImport?.energyCost || 0)}\nVAT Rate: ${productToImport?.taxRate}%`}
            onConfirm={() => {
                if (productToImport) {
                    saveProduct({
                        name: productToImport.name,
                        owner: productToImport.owner,
                        category: 'Printed',
                        price: productToImport.price,
                        cost: productToImport.cost,
                        laborCost: productToImport.laborCost,
                        energyCost: productToImport.energyCost,
                        taxRate: productToImport.taxRate,
                        stock: 0,
                        createdAt: Date.now()
                    }).then(() => {
                        refreshAllData();
                        setProductToImport(null);
                    });
                }
            }}
            onCancel={() => setProductToImport(null)}
            confirmText="Import"
            type="info"
        />

        {/* Mobile Navigation Bottom Bar (Optional if top nav insufficient) */}
        <div className="md:hidden fixed bottom-0 left-0 right-0 bg-white border-t border-gray-200 flex justify-around p-2 z-50">
           <button onClick={() => setActiveView('calculator')} className={clsx("p-2 rounded-lg flex flex-col items-center", activeView === 'calculator' ? "text-brand-600 bg-brand-50" : "text-gray-400")}>
              <Calculator size={20} />
              <span className="text-[9px] mt-1 font-bold">Calc</span>
           </button>
           <button onClick={() => setActiveView('products')} className={clsx("p-2 rounded-lg flex flex-col items-center", activeView === 'products' ? "text-brand-600 bg-brand-50" : "text-gray-400")}>
              <PackageIcon size={20} />
              <span className="text-[9px] mt-1 font-bold">Items</span>
           </button>
           <button onClick={() => setActiveView('pos')} className={clsx("p-2 rounded-lg flex flex-col items-center", activeView === 'pos' ? "text-brand-600 bg-brand-50" : "text-gray-400")}>
              <ShoppingCart size={20} />
              <span className="text-[9px] mt-1 font-bold">POS</span>
           </button>
           <button onClick={() => setActiveView('dashboard')} className={clsx("p-2 rounded-lg flex flex-col items-center", activeView === 'dashboard' ? "text-brand-600 bg-brand-50" : "text-gray-400")}>
              <LayoutDashboard size={20} />
              <span className="text-[9px] mt-1 font-bold">Stats</span>
           </button>
        </div>
    </div>
  );
}

