import React, { useState, useEffect } from 'react';
import { CalculatorInputs, CalculatedResults, HistoryItem, CapitalItem, Product, SaleItem, Sale } from './types';
import { calculateCosts } from './services/calculatorService';
import { parseGCodeFile } from './services/gcodeService';
import { 
  saveJob, getJobs, deleteJob, updateJob,
  saveCapitalItem, getCapitalItems, deleteCapitalItem, updateCapitalItem,
  getProducts, saveProduct, deleteProduct, updateProduct,
  saveSale, getSales, updateSale, deleteSale,
  getSyncStatus
} from './services/firebase';
import { loadSettings, saveSettings, mergeWithDefaults, saveUserDefaults } from './services/settingsService';

// View Components
import { CalculatorView } from './components/CalculatorView';
import { DashboardView } from './components/DashboardView';
import { MathModal } from './components/MathModal';
import { ProductManager } from './components/ProductManager';
import { POSInterface } from './components/POSInterface';
import { ConfirmDialog } from './components/ConfirmDialog';

import { 
  Printer, Calculator, Package as PackageIcon, 
  ShoppingCart, LayoutDashboard, Cloud, Settings, Download, Upload, Loader2, X, Save
} from 'lucide-react';
import clsx from 'clsx';

function App() {
  // --- STATE MANAGEMENT ---
  const [activeView, setActiveView] = useState<'calculator' | 'products' | 'pos' | 'dashboard'>('calculator');

  // Calculator State
  const [inputs, setInputs] = useState<CalculatorInputs>(() => {
    const saved = loadSettings();
    return mergeWithDefaults(saved);
  });
  const [results, setResults] = useState<CalculatedResults>(() => calculateCosts(inputs));
  const [editingJobId, setEditingJobId] = useState<string | null>(null);
  const [isParsing, setIsParsing] = useState(false);
  const [isSaving, setIsSaving] = useState(false);

  // Data State
  const [history, setHistory] = useState<HistoryItem[]>([]);
  const [capitalHistory, setCapitalHistory] = useState<CapitalItem[]>([]);
  const [products, setProducts] = useState<Product[]>([]);
  const [sales, setSales] = useState<Sale[]>([]);
  const [syncStatus] = useState(getSyncStatus());

  // POS State (Lifted)
  const [cart, setCart] = useState<SaleItem[]>([]);

  // UI State
  const [isSidebarOpen, setIsSidebarOpen] = useState(() => {
    if (typeof window !== 'undefined') {
        const saved = localStorage.getItem('bambuCalc_Sidebar');
        return saved !== null ? JSON.parse(saved) : true;
    }
    return true;
  });
  const [showMathModal, setShowMathModal] = useState(false);
  const [showSettingsModal, setShowSettingsModal] = useState(false);

  const [jobToDelete, setJobToDelete] = useState<string | null>(null);
  const [productToDelete, setProductToDelete] = useState<string | null>(null);
  const [saleToDelete, setSaleToDelete] = useState<string | null>(null);
  const [productToImport, setProductToImport] = useState<Omit<Product, 'id' | 'createdAt' | 'stock' | 'category'> | null>(null);
  const [isImporting, setIsImporting] = useState(false);

  // --- EFFECT HOOKS ---

  // Initial Data Load
  const refreshAllData = async () => {
    return Promise.all([
      getJobs(),
      getCapitalItems(),
      getProducts(),
      getSales()
    ]).then(([j, c, p, s]) => {
      setHistory(j);
      setCapitalHistory(c);
      setProducts(p);
      setSales(s);
    });
  };

  useEffect(() => {
    refreshAllData();
  }, []);

  // Recalculate when inputs change
  useEffect(() => {
    setResults(calculateCosts(inputs));
  }, [inputs]);

  // Persist settings
  useEffect(() => {
    saveSettings(inputs);
  }, [inputs]);

  const currency = (val: number) => '₱' + val.toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 });

  // --- HANDLERS ---

  // File Handler
  const handleFile = async (file: File) => {
    setIsParsing(true);
    try {
      const data = await parseGCodeFile(file);
      if (data.found) {
        setInputs(prev => ({
          ...prev,
          timeHours: data.hours,
          timeMinutes: data.minutes,
          materialGrams: data.grams,
          jobName: data.filename?.replace(/\.(gcode|3mf|txt)$/i, '') || prev.jobName
        }));
      } else {
        alert("Could not extract print time or weight from file.");
      }
    } catch (e) {
      console.error(e);
      alert("Error parsing file");
    } finally {
      setIsParsing(false);
    }
  };

  // Job Handlers
  const handleLoadJob = (job: HistoryItem) => {
    setInputs(job.inputs);
    setEditingJobId(job.id);
    setActiveView('calculator');
    if (window.innerWidth < 768) setIsSidebarOpen(false);
  };

  const handleEditJob = (job: HistoryItem) => {
    handleLoadJob(job);
  };

  const handleSaveJob = async (asCopy: boolean) => {
    setIsSaving(true);
    try {
      const jobData = {
        name: inputs.jobName || 'Untitled Job',
        owner: inputs.owner || 'Baz',
        date: new Date().toLocaleDateString(),
        inputs,
        resultsSnapshot: results,
        finalPrice: results.unit.finalPrice,
        status: 'pending' as const,
        createdAt: Date.now()
      };

      if (editingJobId && !asCopy) {
        await updateJob(editingJobId, { ...jobData, updatedAt: Date.now() });
        setEditingJobId(null);
      } else {
        await saveJob(jobData);
      }
      refreshAllData();
    } catch (e) {
      console.error(e);
      alert("Failed to save job");
    } finally {
      setIsSaving(false);
    }
  };

  const handleToggleJobStatus = async (job: HistoryItem) => {
    const newStatus = job.status === 'completed' ? 'pending' : 'completed';
    await updateJob(job.id, { status: newStatus });
    refreshAllData();
  };

  const confirmDeleteJob = async () => {
    if (jobToDelete) {
      await deleteJob(jobToDelete);
      refreshAllData();
      setJobToDelete(null);
    }
  };

  const handleAddToInventory = () => {
      setProductToImport({
          name: inputs.jobName || 'Untitled Print',
          owner: inputs.owner || 'Baz',
          price: results.unit.finalPrice,
          cost: results.unit.productionCost,
          laborCost: results.unit.labor,
          energyCost: results.unit.energy,
          taxRate: typeof inputs.taxRate === 'number' ? inputs.taxRate : parseFloat(inputs.taxRate as string)
      });
      setActiveView('products');
  };

  // Capital Handlers
  const handleAddCapital = async (item: Omit<CapitalItem, 'id'>) => {
    await saveCapitalItem(item);
    refreshAllData();
  };

  const handleUpdateCapital = async (id: string, updates: Partial<CapitalItem>) => {
    await updateCapitalItem(id, updates);
    refreshAllData();
  };

  const confirmDeleteCapital = async (id: string) => {
    await deleteCapitalItem(id);
    refreshAllData();
  };

  // Product Handlers
  const handleAddProduct = async (p: Omit<Product, 'id'>) => {
    await saveProduct(p);
    refreshAllData();
  };

  const handleUpdateProduct = async (id: string, p: Partial<Product>) => {
    await updateProduct(id, p);
    refreshAllData();
  };

  const confirmDeleteProduct = async () => {
    if (productToDelete) {
      await deleteProduct(productToDelete);
      refreshAllData();
      setProductToDelete(null);
    }
  };

  // Sale/POS Handlers
  const handleCheckout = async (paymentMethod: Sale['paymentMethod'], shipping: number) => {
    const timestamp = Date.now();
    // Generate Order ID: ORD-YYMMDD-XXXX
    const datePart = new Date().toISOString().slice(2, 10).replace(/-/g, '');
    const randomPart = Math.random().toString(36).substring(2, 6).toUpperCase();
    const orderId = `ORD-${datePart}-${randomPart}`;

    // Calculate total items value to distribute shipping
    const totalItemsValue = cart.reduce((sum, item) => sum + (item.unitPrice * item.quantity), 0);

    // Track distributed shipping to handle penny rounding on the last item
    let distributedShipping = 0;

    for (let i = 0; i < cart.length; i++) {
        const item = cart[i];

        // Optimistic Stock Update
        if (item.type === 'product') {
            const product = products.find(p => p.id === item.refId);
            if (product) {
                await updateProduct(product.id, { stock: Math.max(0, product.stock - item.quantity) });
            }
        }

        const itemRevenue = item.unitPrice * item.quantity;
        const itemCost = item.unitCost * item.quantity;

        // Calculate proportional shipping for this line item
        let itemShipping = 0;
        if (totalItemsValue > 0) {
            if (i === cart.length - 1) {
                // Last item gets the remainder to ensure exact total match
                itemShipping = shipping - distributedShipping;
            } else {
                // Proportional share
                const share = itemRevenue / totalItemsValue;
                itemShipping = Number((shipping * share).toFixed(2));
                distributedShipping += itemShipping;
            }
        }

        // Ensure no undefined values are passed to Firebase
        const sanitizedItem = {
            ...item,
            itemOwner: item.itemOwner || 'Baz',
            laborCost: item.laborCost ?? 0,
            energyCost: item.energyCost ?? 0,
            taxRate: item.taxRate ?? 0
        };

        const sale: Omit<Sale, 'id'> = {
            orderId, // Link all items to this order
            items: [sanitizedItem],
            // Revenue includes the item price AND the collected shipping
            totalRevenue: itemRevenue + itemShipping, 
            totalCost: itemCost,
            // Profit is strictly Item Price - Item Cost. Shipping is assumed pass-through (Revenue cancels Cost).
            // If we included shipping in profit, it would imply we didn't pay the courier.
            totalProfit: itemRevenue - itemCost,
            paymentMethod,
            owner: sanitizedItem.itemOwner, 
            shipping: itemShipping, // Record the distributed shipping amount
            timestamp: timestamp,
            dateStr: new Date().toLocaleDateString()
        };

        await saveSale(sale);
    }

    setCart([]);
    refreshAllData();
  };

  const handleUpdateSale = async (id: string, updates: Partial<Sale>) => {
    await updateSale(id, updates);
    refreshAllData();
  };

  const confirmDeleteSale = async () => {
    if (saleToDelete) {
      await deleteSale(saleToDelete);
      refreshAllData();
      setSaleToDelete(null);
    }
  };

  // --- BACKUP / RESTORE LOGIC ---

  const handleSaveDefaults = () => {
      saveUserDefaults(inputs);
      alert("Current settings saved as default!");
  };

  const handleExportData = () => {
      const data = {
          jobs: history,
          products: products,
          sales: sales,
          capital: capitalHistory,
          exportedAt: new Date().toISOString()
      };

      const jsonString = JSON.stringify(data, null, 2);
      const blob = new Blob([jsonString], { type: 'application/json' });
      const url = URL.createObjectURL(blob);
      const link = document.createElement('a');
      link.href = url;
      link.download = `3d_print_data_backup_${new Date().toISOString().split('T')[0]}.json`;
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
  };

  const handleImportData = async (e: React.ChangeEvent<HTMLInputElement>) => {
      if (!e.target.files || !e.target.files[0]) return;
      const file = e.target.files[0];

      setIsImporting(true);
      try {
          const text = await file.text();
          const data = JSON.parse(text);

          const [exJobs, exProducts, exSales, exCapital] = await Promise.all([
             getJobs(2000), 
             getProducts(),
             getSales(2000),
             getCapitalItems(2000)
          ]);

          const jobTimestamps = new Set(exJobs.map(j => j.createdAt));
          const productNames = new Set(exProducts.map(p => p.name.toLowerCase()));
          const saleTimestamps = new Set(exSales.map(s => s.timestamp));
          const getCapKey = (c: any) => `${c.name}|${c.purchaseDate}|${c.price}`;
          const capitalKeys = new Set(exCapital.map(c => getCapKey(c)));

          let added = 0;
          let skipped = 0;

          // Import Jobs
          if (data.jobs && Array.isArray(data.jobs)) {
              for (const job of data.jobs) {
                 if (job.createdAt && jobTimestamps.has(job.createdAt)) {
                     skipped++; continue;
                 }
                 const { id, ...rest } = job; 
                 await saveJob(rest);
                 added++;
              }
          }

          // Import Products
          if (data.products && Array.isArray(data.products)) {
              for (const p of data.products) {
                  if (p.name && productNames.has(p.name.toLowerCase())) {
                      skipped++; continue;
                  }
                  const { id, ...rest } = p;
                  await saveProduct(rest);
                  added++;
              }
          }

          // Import Sales
          if (data.sales && Array.isArray(data.sales)) {
              for (const s of data.sales) {
                  if (s.timestamp && saleTimestamps.has(s.timestamp)) {
                      skipped++; continue;
                  }
                  const { id, ...rest } = s;
                  await saveSale(rest);
                  added++;
              }
          }

          // Import Capital
          if (data.capital && Array.isArray(data.capital)) {
              for (const c of data.capital) {
                  const key = getCapKey(c);
                  if (capitalKeys.has(key)) {
                      skipped++; continue;
                  }
                  const { id, ...rest } = c;
                  await saveCapitalItem(rest);
                  added++;
              }
          }

          alert(`Import successful!\n\n✅ Added: ${added} new records\n🚫 Skipped: ${skipped} duplicates`);
          await refreshAllData();
          setShowSettingsModal(false);

      } catch (err) {
          console.error(err);
          alert("Failed to import file. Invalid format or corrupt file.");
      } finally {
          setIsImporting(false);
          // Reset file input
          e.target.value = '';
      }
  };

  // Navigation Helper
  const NavItem = ({ view, icon: Icon, label }: { view: typeof activeView, icon: any, label: string }) => (
    <button 
      onClick={() => setActiveView(view)}
      className={clsx(
          "flex items-center gap-2 px-4 py-2 rounded-lg transition-colors text-sm font-bold",
          activeView === view ? "bg-brand-600 text-white" : "text-gray-600 hover:bg-gray-100"
      )}
    >
        <Icon size={18} />
        <span className="hidden md:inline">{label}</span>
    </button>
  );

  return (
    <div className="flex flex-col h-screen bg-white">
        {/* Top Navigation */}
        <header className="flex items-center justify-between px-6 py-3 border-b border-gray-200 flex-none bg-white z-40">
            <div className="flex items-center gap-3">
                <div className="bg-brand-600 text-white p-2 rounded-lg">
                    <Printer size={20} />
                </div>
                <div>
                    <h1 className="font-black text-lg text-gray-900 leading-none">BambuCalc</h1>
                    <div className="flex items-center gap-1 text-[10px] text-gray-400 font-medium">
                        <Cloud size={10} /> {syncStatus.isCloud ? 'Cloud Sync Active' : 'Local Mode'}
                    </div>
                </div>
            </div>

            <nav className="flex items-center gap-2 bg-gray-50 p-1 rounded-xl border border-gray-100 hidden md:flex">
                <NavItem view="calculator" icon={Calculator} label="Calculator" />
                <NavItem view="products" icon={PackageIcon} label="Inventory" />
                <NavItem view="pos" icon={ShoppingCart} label="POS" />
                <NavItem view="dashboard" icon={LayoutDashboard} label="Dashboard" />
            </nav>

            {/* Mobile Nav Dropdown Placeholder (Simplified for now) */}
            <div className="md:hidden">
               <button onClick={() => setActiveView(activeView === 'calculator' ? 'dashboard' : 'calculator')} className="text-gray-600">
                  <LayoutDashboard />
               </button>
            </div>

            <div className="flex items-center gap-2 md:w-32 justify-end">
                 <button 
                    onClick={() => setShowSettingsModal(true)}
                    className="p-2 text-gray-400 hover:text-gray-900 hover:bg-gray-100 rounded-lg transition-all"
                    title="Settings & Data"
                 >
                    <Settings size={20} />
                 </button>
            </div>
        </header>

        {/* Main View Area */}
        <main className="flex-1 overflow-hidden relative">
            {activeView === 'calculator' && (
                <CalculatorView 
                    inputs={inputs}
                    setInputs={setInputs}
                    results={results}
                    history={history}
                    editingJobId={editingJobId}
                    isSaving={isSaving}
                    isSidebarOpen={isSidebarOpen}
                    setIsSidebarOpen={setIsSidebarOpen}
                    onLoadJob={handleLoadJob}
                    onEditJob={handleEditJob}
                    onDeleteJob={id => setJobToDelete(id)}
                    onSaveJob={handleSaveJob}
                    onCancel={() => { setEditingJobId(null); setInputs(mergeWithDefaults({})); }}
                    onShowMath={() => setShowMathModal(true)}
                    onShowDashboard={() => setActiveView('dashboard')}
                    onAddToInventory={handleAddToInventory}
                    handleFile={handleFile}
                    isParsing={isParsing}
                    currency={currency}
                    onToggleJobStatus={handleToggleJobStatus}
                />
            )}

            {activeView === 'products' && (
                <ProductManager 
                    products={products}
                    onAdd={handleAddProduct}
                    onUpdate={handleUpdateProduct}
                    onDelete={id => setProductToDelete(id)}
                    currency={currency}
                />
            )}

            {activeView === 'pos' && (
                <POSInterface 
                    products={products}
                    jobs={history}
                    cart={cart}
                    currency={currency}
                    onAddToCart={item => {
                        const existing = cart.findIndex(c => c.type === item.type && c.refId === item.refId);
                        if (existing >= 0) {
                            const newCart = [...cart];
                            newCart[existing].quantity += item.quantity;
                            setCart(newCart);
                        } else {
                            setCart([...cart, item]);
                        }
                    }}
                    onUpdateCartQty={(idx, delta) => {
                         const newCart = [...cart];
                         newCart[idx].quantity += delta;
                         if (newCart[idx].quantity <= 0) newCart.splice(idx, 1);
                         setCart(newCart);
                    }}
                    onRemoveFromCart={idx => {
                        const newCart = [...cart];
                        newCart.splice(idx, 1);
                        setCart(newCart);
                    }}
                    onCheckout={handleCheckout}
                    onClearCart={() => setCart([])}
                />
            )}

            {activeView === 'dashboard' && (
                <DashboardView 
                    history={history}
                    capitalHistory={capitalHistory}
                    sales={sales}
                    onDeleteJob={id => setJobToDelete(id)}
                    onAddCapital={handleAddCapital}
                    onUpdateCapital={handleUpdateCapital}
                    onDeleteCapital={confirmDeleteCapital}
                    onUpdateSale={handleUpdateSale}
                    onDeleteSale={id => setSaleToDelete(id)}
                    currency={currency}
                />
            )}
        </main>

        {/* Modals & Dialogs (Unchanged) */}
        <MathModal 
            isOpen={showMathModal} 
            onClose={() => setShowMathModal(false)}
            inputs={inputs}
            results={results}
            currency={currency}
        />

        {showSettingsModal && (
          <div className="fixed inset-0 z-[70] flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm animate-in fade-in duration-200">
             <div className="bg-white rounded-2xl w-full max-w-md p-6 shadow-2xl border border-gray-100">
                 <div className="flex justify-between items-center mb-6">
                    <h2 className="text-lg font-bold text-gray-900 flex items-center gap-2">
                        <Settings className="text-brand-600" /> Settings & Data
                    </h2>
                    <button onClick={() => setShowSettingsModal(false)} className="text-gray-400 hover:text-gray-600">
                        <X size={20} />
                    </button>
                 </div>

                 <div className="space-y-4">
                     <div className="bg-gray-50 p-4 rounded-xl border border-gray-100">
                         <h3 className="text-sm font-bold text-gray-800 mb-2">Calculator Defaults</h3>
                         <p className="text-xs text-gray-500 mb-3">Save current calculator values (Material Cost, Rates, Fees) as the default for new jobs.</p>
                         <button 
                            onClick={handleSaveDefaults}
                            className="w-full flex items-center justify-center gap-2 bg-white border border-gray-200 hover:border-brand-500 text-gray-700 hover:text-brand-600 font-bold py-2 rounded-lg transition-colors text-sm shadow-sm"
                         >
                             <Save size={16} /> Save Current as Default
                         </button>
                     </div>

                     <div className="bg-gray-50 p-4 rounded-xl border border-gray-100">
                         <h3 className="text-sm font-bold text-gray-800 mb-2">Backup Data</h3>
                         <p className="text-xs text-gray-500 mb-3">Download a JSON file containing all jobs, products, sales, and expenses.</p>
                         <button 
                            onClick={handleExportData}
                            className="w-full flex items-center justify-center gap-2 bg-white border border-gray-200 hover:border-brand-500 text-gray-700 hover:text-brand-600 font-bold py-2 rounded-lg transition-colors text-sm shadow-sm"
                         >
                             <Download size={16} /> Download Backup
                         </button>
                     </div>

                     <div className="bg-gray-50 p-4 rounded-xl border border-gray-100">
                         <h3 className="text-sm font-bold text-gray-800 mb-2">Restore Data</h3>
                         <p className="text-xs text-gray-500 mb-3">Import data from a backup file. Existing records will be skipped.</p>
                         <div className="relative">
                            <input 
                                type="file" 
                                accept=".json" 
                                onChange={handleImportData}
                                className="absolute inset-0 w-full h-full opacity-0 cursor-pointer"
                                disabled={isImporting}
                            />
                            <button 
                                className="w-full flex items-center justify-center gap-2 bg-brand-600 hover:bg-brand-700 text-white font-bold py-2 rounded-lg transition-colors text-sm shadow-md disabled:opacity-50"
                                disabled={isImporting}
                            >
                                {isImporting ? <Loader2 className="animate-spin" size={16} /> : <Upload size={16} />}
                                {isImporting ? 'Importing...' : 'Upload Backup File'}
                            </button>
                         </div>
                     </div>
                 </div>

                 <div className="mt-6 text-center text-[10px] text-gray-400">
                     v1.3.0 • Cloud Sync Active
                 </div>
             </div>
          </div>
        )}

        <ConfirmDialog 
            isOpen={!!jobToDelete}
            title="Delete Job?"
            message="This action cannot be undone."
            onConfirm={confirmDeleteJob}
            onCancel={() => setJobToDelete(null)}
        />

        <ConfirmDialog 
            isOpen={!!productToDelete}
            title="Delete Product?"
            message="Are you sure? This will remove the product from inventory and POS."
            onConfirm={confirmDeleteProduct}
            onCancel={() => setProductToDelete(null)}
        />

        <ConfirmDialog 
            isOpen={!!saleToDelete}
            title="Delete Sale Record?"
            message="This will remove the transaction from your ledger."
            onConfirm={confirmDeleteSale}
            onCancel={() => setSaleToDelete(null)}
        />

        <ConfirmDialog 
            isOpen={!!productToImport}
            title="Import to Inventory"
            message={`Add "${productToImport?.name}" to Inventory?\nRecommended Price: ${currency(productToImport?.price || 0)}\nCost Basis: ${currency(productToImport?.cost || 0)}\nLabor: ${currency(productToImport?.laborCost || 0)}\nEnergy: ${currency(productToImport?.energyCost || 0)}\nVAT Rate: ${productToImport?.taxRate}%`}
            onConfirm={() => {
                if (productToImport) {
                    saveProduct({
                        name: productToImport.name,
                        owner: productToImport.owner,
                        category: 'Printed',
                        price: productToImport.price,
                        cost: productToImport.cost,
                        laborCost: productToImport.laborCost,
                        energyCost: productToImport.energyCost,
                        taxRate: productToImport.taxRate,
                        stock: 0,
                        createdAt: Date.now()
                    }).then(() => {
                        refreshAllData();
                        setProductToImport(null);
                    });
                }
            }}
            onCancel={() => setProductToImport(null)}
            confirmText="Import"
            type="info"
        />

        {/* Mobile Navigation Bottom Bar (Optional if top nav insufficient) */}
        <div className="md:hidden fixed bottom-0 left-0 right-0 bg-white border-t border-gray-200 flex justify-around p-2 z-50">
           <button onClick={() => setActiveView('calculator')} className={clsx("p-2 rounded-lg flex flex-col items-center", activeView === 'calculator' ? "text-brand-600 bg-brand-50" : "text-gray-400")}>
              <Calculator size={20} />
              <span className="text-[9px] mt-1 font-bold">Calc</span>
           </button>
           <button onClick={() => setActiveView('products')} className={clsx("p-2 rounded-lg flex flex-col items-center", activeView === 'products' ? "text-brand-600 bg-brand-50" : "text-gray-400")}>
              <PackageIcon size={20} />
              <span className="text-[9px] mt-1 font-bold">Items</span>
           </button>
           <button onClick={() => setActiveView('pos')} className={clsx("p-2 rounded-lg flex flex-col items-center", activeView === 'pos' ? "text-brand-600 bg-brand-50" : "text-gray-400")}>
              <ShoppingCart size={20} />
              <span className="text-[9px] mt-1 font-bold">POS</span>
           </button>
           <button onClick={() => setActiveView('dashboard')} className={clsx("p-2 rounded-lg flex flex-col items-center", activeView === 'dashboard' ? "text-brand-600 bg-brand-50" : "text-gray-400")}>
              <LayoutDashboard size={20} />
              <span className="text-[9px] mt-1 font-bold">Stats</span>
           </button>
        </div>
    </div>
  );
}

export default App;

import React, { useMemo, useState } from 'react';
import { HistoryItem, CapitalItem, Sale } from '../types';
import { OWNERS } from '../constants';
import { Download, TrendingUp, DollarSign, Wallet, ShoppingCart, Edit2, X, Trash2, Plus, Calendar, User, Truck, Tag, Link as LinkIcon, Store, Search, ArrowUp, ArrowDown, Zap, Users, PieChart, CreditCard, Hash } from 'lucide-react';
import clsx from 'clsx';

interface DashboardViewProps {
  history: HistoryItem[];
  capitalHistory: CapitalItem[];
  sales: Sale[];
  onDeleteJob: (id: string) => void;
  onAddCapital: (item: Omit<CapitalItem, 'id'>) => Promise<void>;
  onUpdateCapital: (id: string, updates: Partial<CapitalItem>) => Promise<void>;
  onDeleteCapital: (id: string) => void;
  onUpdateSale: (id: string, updates: Partial<Sale>) => Promise<void>;
  onDeleteSale: (id: string) => void;
  currency: (val: number) => string;
}

interface SortConfig {
    key: string;
    direction: 'asc' | 'desc';
}

export const DashboardView: React.FC<DashboardViewProps> = ({ 
  history, capitalHistory, sales,
  onDeleteJob, onAddCapital, onUpdateCapital, onDeleteCapital, onUpdateSale, onDeleteSale, currency 
}) => {
  const [activeTab, setActiveTab] = React.useState<'sales' | 'expenses'>('sales');

  // Sale Edit State
  const [editingSale, setEditingSale] = useState<Sale | null>(null);

  // Sorting & Searching State
  const [searchTerm, setSearchTerm] = useState('');
  const [sortConfig, setSortConfig] = useState<SortConfig>({ key: 'date', direction: 'desc' });

  // Date Filtering State
  const [dateRange, setDateRange] = useState({ start: '', end: '' });

  // Expense Add/Edit State
  const [isAddingExpense, setIsAddingExpense] = useState(false);
  const [editingExpenseId, setEditingExpenseId] = useState<string | null>(null);

  const DEFAULT_EXPENSE = {
      name: '',
      category: 'Parts',
      platform: 'Shopee',
      store: '',
      purchaseDate: new Date().toISOString().split('T')[0],
      dateReceived: '',
      orderedBy: 'Baz',
      paidBy: 'Baz',
      receiptLink: '',
      remarks: '',
      quantity: 1,
      unitPrice: ''
  };

  const [newExpense, setNewExpense] = useState<{
      name: string;
      category: string;
      platform: string;
      store: string;
      purchaseDate: string;
      dateReceived?: string;
      orderedBy: string;
      paidBy: string;
      receiptLink?: string;
      remarks?: string;
      quantity: number | '';
      unitPrice: string;
  }>(DEFAULT_EXPENSE);

  // Helper: Format Date to mm/dd/yyyy
  const formatDate = (dateStr: string) => {
      if (!dateStr) return '-';
      const date = new Date(dateStr);
      if (isNaN(date.getTime())) return dateStr; // Return original if parse fails
      return date.toLocaleDateString('en-US', {
          year: 'numeric',
          month: '2-digit',
          day: '2-digit'
      });
  };

  const handleStartDateChange = (e: React.ChangeEvent<HTMLInputElement>) => {
      const startVal = e.target.value;

      let nextEnd = dateRange.end;

      if (startVal) {
          const d = new Date(startVal);
          // Sunday is 0, Saturday is 6.
          const currentDay = d.getDay();
          // Calculate days to add to reach next Saturday
          const daysToSaturday = 6 - currentDay;

          const endDate = new Date(d);
          endDate.setDate(d.getDate() + daysToSaturday);

          // Format to YYYY-MM-DD for input value
          nextEnd = endDate.toISOString().split('T')[0];
      }

      setDateRange({ start: startVal, end: nextEnd });
  };

  // Handle Sort
  const handleSort = (key: string) => {
      setSortConfig(current => ({
          key,
          direction: current.key === key && current.direction === 'asc' ? 'desc' : 'asc'
      }));
  };

  // Filter and Sort Sales
  const processedSales = useMemo(() => {
      let result = [...sales];

      // 1. Search
      if (searchTerm) {
          const lower = searchTerm.toLowerCase();
          result = result.filter(s => 
              s.dateStr.toLowerCase().includes(lower) || 
              s.paymentMethod.toLowerCase().includes(lower) || 
              s.orderId?.toLowerCase().includes(lower) ||
              s.items.some(i => i.name.toLowerCase().includes(lower))
          );
      }

      // 2. Date Filter
      if (dateRange.start) {
        const startTs = new Date(dateRange.start).setHours(0,0,0,0);
        result = result.filter(s => s.timestamp >= startTs);
      }
      if (dateRange.end) {
        const endTs = new Date(dateRange.end).setHours(23,59,59,999);
        result = result.filter(s => s.timestamp <= endTs);
      }

      // 3. Sort
      result.sort((a, b) => {
          let valA: number | string = 0;
          let valB: number | string = 0;

          // Helper to calculate virtual columns
          const getLabor = (s: Sale) => s.items.reduce((acc, i) => acc + ((i.laborCost||0)*i.quantity), 0);
          const getEnergy = (s: Sale) => s.items.reduce((acc, i) => acc + ((i.energyCost||0)*i.quantity), 0);

          switch(sortConfig.key) {
              case 'date':
                  valA = a.timestamp;
                  valB = b.timestamp;
                  break;
              case 'labor':
                  valA = getLabor(a);
                  valB = getLabor(b);
                  break;
              case 'energy':
                  valA = getEnergy(a);
                  valB = getEnergy(b);
                  break;
              case 'orderId':
                  valA = a.orderId || '';
                  valB = b.orderId || '';
                  break;
              default:
                  // @ts-ignore
                  valA = a[sortConfig.key];
                  // @ts-ignore
                  valB = b[sortConfig.key];
          }

          if (valA < valB) return sortConfig.direction === 'asc' ? -1 : 1;
          if (valA > valB) return sortConfig.direction === 'asc' ? 1 : -1;
          return 0;
      });
      return result;
  }, [sales, searchTerm, sortConfig, dateRange]);

  // Filter and Sort Expenses
  const processedExpenses = useMemo(() => {
    let result = [...capitalHistory];

    // 1. Search
    if (searchTerm) {
        const lower = searchTerm.toLowerCase();
        result = result.filter(e => 
            e.name.toLowerCase().includes(lower) ||
            e.store.toLowerCase().includes(lower) ||
            e.platform.toLowerCase().includes(lower) || 
            e.category.toLowerCase().includes(lower)
        );
    }

    // 2. Date Filter
    if (dateRange.start) {
       result = result.filter(e => e.purchaseDate >= dateRange.start);
    }
    if (dateRange.end) {
       result = result.filter(e => e.purchaseDate <= dateRange.end);
    }

    // 3. Sort
    result.sort((a, b) => {
        let valA: any = a[sortConfig.key as keyof CapitalItem];
        let valB: any = b[sortConfig.key as keyof CapitalItem];

        // Special Keys
        if (sortConfig.key === 'date') {
            valA = new Date(a.purchaseDate).getTime();
            valB = new Date(b.purchaseDate).getTime();
        }

        if (typeof valA === 'string') {
            valA = valA.toLowerCase();
            valB = valB.toLowerCase();
        }

        if (valA < valB) return sortConfig.direction === 'asc' ? -1 : 1;
        if (valA > valB) return sortConfig.direction === 'asc' ? 1 : -1;
        return 0;
    });
    return result;
  }, [capitalHistory, searchTerm, sortConfig, dateRange]);

  // Calculate aggregates (Based on Filtered Data)
  const stats = useMemo(() => {
    // 1. Sales Revenue (Realized)
    let totalSalesRev = 0;
    let totalSalesProfit = 0;
    let totalTaxCollected = 0;
    let allocatedLabor = 0;
    let allocatedEnergy = 0;

    processedSales.forEach(s => {
      totalSalesRev += s.totalRevenue;
      totalSalesProfit += s.totalProfit;

      // Calculate tax portion for stats
      if (s.items) {
          s.items.forEach(i => {
              const rate = i.taxRate || 0;
              const netPrice = i.unitPrice / (1 + (rate/100));
              totalTaxCollected += (i.unitPrice - netPrice) * i.quantity;

              // Labor & Energy Accumulation
              if (i.laborCost) allocatedLabor += i.laborCost * i.quantity;
              if (i.energyCost) allocatedEnergy += i.energyCost * i.quantity;
          });
      }
    });

    // 3. Capital
    const totalCapital = processedExpenses.reduce((acc, curr) => acc + (curr.price || 0), 0);
    const netPosition = totalSalesProfit - totalCapital;

    return { totalSalesRev, totalSalesProfit, totalCapital, netPosition, totalTaxCollected, allocatedLabor, allocatedEnergy };
  }, [processedSales, processedExpenses]);

  // Calculate Breakdowns
  const breakdowns = useMemo(() => {
      const salesByMethod: Record<string, number> = {};
      processedSales.forEach(s => {
          const method = s.paymentMethod || 'other';
          salesByMethod[method] = (salesByMethod[method] || 0) + s.totalRevenue;
      });

      const expensesByCategory: Record<string, number> = {};
      const expensesByPayer: Record<string, number> = {};

      processedExpenses.forEach(e => {
          // Category Breakdown
          const cat = e.category || 'Other';
          expensesByCategory[cat] = (expensesByCategory[cat] || 0) + e.price;

          // Payer Breakdown
          const payer = e.paidBy || 'Unknown';
          expensesByPayer[payer] = (expensesByPayer[payer] || 0) + e.price;
      });

      return { salesByMethod, expensesByCategory, expensesByPayer };
  }, [processedSales, processedExpenses]);


  const downloadCSV = () => {
      let content = "";
      let filename = "";

      if (activeTab === 'sales') {
        const headers = ['Order ID', 'Date', 'Type', 'Owner', 'Total', 'Shipping', 'VAT', 'Profit', 'Labor Cost', 'Energy Cost', 'Payment'];
        const rows = processedSales.map(s => {
            let tax = 0;
            let labor = 0;
            let energy = 0;
            s.items.forEach(i => {
                const rate = i.taxRate || 0;
                const net = i.unitPrice / (1 + (rate/100));
                tax += (i.unitPrice - net) * i.quantity;
                labor += (i.laborCost || 0) * i.quantity;
                energy += (i.energyCost || 0) * i.quantity;
            });
            return [
                s.orderId || '-',
                formatDate(s.dateStr), 
                'Sale', 
                s.owner || '-',
                s.totalRevenue.toFixed(2), 
                s.shipping?.toFixed(2) || '0.00',
                tax.toFixed(2), 
                s.totalProfit.toFixed(2), 
                labor.toFixed(2),
                energy.toFixed(2),
                s.paymentMethod
            ].join(',');
        });
        content = [headers.join(','), ...rows].join('\n');
        filename = 'sales_ledger.csv';
      } else {
        const headers = ['Purchase Date', 'Item', 'Qty', 'Category', 'Total Price', 'Store', 'Platform', 'Ordered By', 'Paid By'];
        const rows = processedExpenses.map(c => [
            formatDate(c.purchaseDate), c.name, c.quantity || 1, c.category, c.price.toFixed(2), c.store, c.platform, c.orderedBy, c.paidBy
        ].join(','));
        content = [headers.join(','), ...rows].join('\n');
        filename = 'capital_expenses.csv';
      }

      const csvContent = "data:text/csv;charset=utf-8," + encodeURI(content);
      const link = document.createElement("a");
      link.setAttribute("href", csvContent);
      link.setAttribute("download", filename);
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
  };

  const handleSaveSaleEdit = async () => {
      if (!editingSale) return;
      const newProfit = editingSale.totalRevenue - editingSale.totalCost; // Simplified logic, assumes cost doesn't change
      await onUpdateSale(editingSale.id, {
          dateStr: editingSale.dateStr,
          paymentMethod: editingSale.paymentMethod,
          owner: editingSale.owner || 'Baz',
          totalRevenue: editingSale.totalRevenue,
          totalProfit: newProfit
      });
      setEditingSale(null);
  };

  const handleEditExpense = (item: CapitalItem) => {
      setNewExpense({
          name: item.name,
          category: item.category,
          platform: item.platform || '',
          store: item.store || '',
          purchaseDate: item.purchaseDate,
          dateReceived: item.dateReceived || '',
          orderedBy: item.orderedBy || 'Baz',
          paidBy: item.paidBy || 'Baz',
          receiptLink: item.receiptLink || '',
          remarks: item.remarks || '',
          quantity: item.quantity || 1,
          unitPrice: item.quantity > 0 ? (item.price / item.quantity).toFixed(2) : item.price.toFixed(2)
      });
      setEditingExpenseId(item.id);
      setIsAddingExpense(true);
  };

  const closeExpenseModal = () => {
      setIsAddingExpense(false);
      setEditingExpenseId(null);
      setNewExpense(DEFAULT_EXPENSE);
  };

  const handleSaveExpense = async (e: React.FormEvent) => {
      e.preventDefault();

      const qty = Number(newExpense.quantity) || 1;
      const unit = parseFloat(newExpense.unitPrice) || 0;
      const total = unit * qty;

      if (!newExpense.name || total <= 0) {
          alert("Please enter a valid Name and Price.");
          return;
      }

      const expenseData = {
          name: newExpense.name,
          price: total,
          quantity: qty,
          category: newExpense.category as any,
          platform: newExpense.platform || '',
          store: newExpense.store || '',
          purchaseDate: newExpense.purchaseDate || new Date().toLocaleDateString(),
          dateReceived: newExpense.dateReceived || null,
          orderedBy: newExpense.orderedBy || 'Baz',
          paidBy: newExpense.paidBy || 'Baz',
          receiptLink: newExpense.receiptLink || null,
          remarks: newExpense.remarks || null,
      };

      try {
        if (editingExpenseId) {
            await onUpdateCapital(editingExpenseId, expenseData);
        } else {
            await onAddCapital({
                ...expenseData,
                createdAt: Date.now()
            });
